import type { RequestHandler } from 'express';
import type { AppConfig } from '../config/env';
import { getPrismaClient } from '../db/prisma';
import { AppError } from '../utils/errors';
import { verifyAccessToken } from '../modules/auth/access-token.service';
import { findActiveSession } from '../modules/auth/session.service';

/**
 * Request guards for authenticated routes.
 *
 * The access token is a short-lived JWT, but the referenced session is always
 * checked against PostgreSQL before a request is trusted. That makes logout,
 * "log out other devices", password resets and suspensions effective
 * immediately instead of waiting for the access token to expire.
 */

export interface AuthContext {
  userId: string;
  sessionId: string;
  email: string;
  name: string;
  status: 'PENDING_VERIFICATION' | 'ACTIVE' | 'SUSPENDED' | 'DEACTIVATED' | 'PENDING_DELETION';
  authMethod: 'password' | 'social' | 'sso' | 'break_glass';
  authMethodExpiresAt?: Date | null;
}

function extractBearerToken(header: string | undefined): string | null {
  if (!header) {
    return null;
  }

  const [scheme, ...rest] = header.split(' ');

  if (!scheme || scheme.toLowerCase() !== 'bearer') {
    return null;
  }

  const token = rest.join(' ').trim();

  return token.length > 0 ? token : null;
}

export function createRequireAuth(config: AppConfig): RequestHandler {
  return async (req, _res, next) => {
    try {
      const token = extractBearerToken(req.header('authorization'));

      if (!token) {
        throw new AppError(401, 'AUTHENTICATION_REQUIRED', 'You must be signed in to continue');
      }

      const claims = verifyAccessToken(config, token);
      const session = await findActiveSession(getPrismaClient(), claims.sid);

      if (!session || session.userId !== claims.sub) {
        throw new AppError(
          401,
          'SESSION_REVOKED',
          'Your session is no longer valid. Please sign in again.',
        );
      }

      const user = await getPrismaClient().user.findUnique({
        where: { id: claims.sub },
        select: { id: true, email: true, name: true, status: true, deletedAt: true },
      });

      if (!user || user.deletedAt) {
        throw new AppError(401, 'SESSION_REVOKED', 'Your session is no longer valid.');
      }

      if (user.status === 'SUSPENDED') {
        throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
      }

      if (user.status === 'DEACTIVATED') {
        throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deactivated');
      }

      if (user.status === 'PENDING_DELETION') {
        throw new AppError(
          403,
          'ACCOUNT_PENDING_DELETION',
          'This account is being deleted and can no longer access Nexus.',
        );
      }

      const rawMethod = String((session as any).authMethod ?? 'PASSWORD').toLowerCase();
      const authMethod = (['password','social','sso','break_glass'] as const).includes(rawMethod as any)
        ? (rawMethod as AuthContext['authMethod'])
        : 'password';

      // Break-glass sessions are time-limited by authMethodExpiresAt in addition to normal session expiry.
      if (authMethod === 'break_glass' && (session as any).authMethodExpiresAt) {
        const amExp = new Date((session as any).authMethodExpiresAt).getTime();
        if (amExp <= Date.now()) {
          throw new AppError(401, 'SESSION_EXPIRED', 'Your break-glass session has expired. Please sign in again.');
        }
      }

      req.auth = {
        userId: user.id,
        sessionId: session.id,
        email: user.email,
        name: user.name,
        status: user.status,
        authMethod,
        authMethodExpiresAt: (session as any).authMethodExpiresAt ?? null,
      };

      next();
    } catch (error) {
      next(error);
    }
  };
}

/**
 * Guard for endpoints that require a fully activated account.
 *
 * Accounts that are still `PENDING_VERIFICATION` may authenticate (so they can
 * read their own status and request a new verification link) but must not
 * reach protected business endpoints.
 */
export function requireActiveAccount(req: { auth?: AuthContext }): void {
  if (!req.auth) {
    throw new AppError(401, 'AUTHENTICATION_REQUIRED', 'You must be signed in to continue');
  }

  if (req.auth.status === 'PENDING_VERIFICATION') {
    throw new AppError(403, 'EMAIL_NOT_VERIFIED', 'Verify your email address to continue');
  }
}

/**
 * Guard for endpoints that require a fully activated account.
 */
export function createRequireActiveAccount(): RequestHandler {
  return (req, _res, next) => {
    try {
      requireActiveAccount(req);
      next();
    } catch (error) {
      next(error);
    }
  };
}

import jwt from 'jsonwebtoken';
import type { AppConfig } from '../../config/env';
import { AppError } from '../../utils/errors';

/**
 * Short-lived access tokens.
 *
 * Access tokens are JWTs so that ordinary API calls do not require a database
 * round trip for signature verification. Revocation is still authoritative:
 * the request guard verifies the referenced session against PostgreSQL before
 * trusting a token, so logging out or changing a password takes effect
 * immediately.
 */

export type SessionAuthMethodClaim = 'password' | 'social' | 'sso' | 'break_glass';

export interface AccessTokenClaims {
  /** User id. */
  sub: string;
  /** Session id, used to enforce revocation. */
  sid: string;
  /** Authentication method for this session. */
  amr?: SessionAuthMethodClaim;
  /** Token type guard, so a refresh token can never be used as an access token. */
  typ: 'access';
}

export function signAccessToken(
  config: AppConfig,
  payload: { userId: string; sessionId: string; authMethod?: SessionAuthMethodClaim },
): { token: string; expiresIn: number } {
  const token = jwt.sign(
    {
      sub: payload.userId,
      sid: payload.sessionId,
      ...(payload.authMethod ? { amr: payload.authMethod } : {}),
      typ: 'access' as const,
    },
    config.jwtAccessSecret,
    {
      algorithm: 'HS256',
      expiresIn: config.jwtAccessTtlSeconds,
      issuer: 'nexus-backend',
      audience: 'nexus-api',
    },
  );

  return { token, expiresIn: config.jwtAccessTtlSeconds };
}

export function verifyAccessToken(config: AppConfig, token: string): AccessTokenClaims {
  let decoded: unknown;

  try {
    decoded = jwt.verify(token, config.jwtAccessSecret, {
      algorithms: ['HS256'],
      issuer: 'nexus-backend',
      audience: 'nexus-api',
    });
  } catch (error) {
    const expired = error instanceof jwt.TokenExpiredError;

    throw new AppError(
      401,
      expired ? 'ACCESS_TOKEN_EXPIRED' : 'ACCESS_TOKEN_INVALID',
      expired ? 'Your session has expired. Please sign in again.' : 'The access token is invalid',
    );
  }

  if (typeof decoded !== 'object' || decoded === null) {
    throw new AppError(401, 'ACCESS_TOKEN_INVALID', 'The access token is invalid');
  }

  const claims = decoded as Partial<AccessTokenClaims>;

  if (
    claims.typ !== 'access' ||
    typeof claims.sub !== 'string' ||
    typeof claims.sid !== 'string' ||
    claims.sub.length === 0 ||
    claims.sid.length === 0
  ) {
    throw new AppError(401, 'ACCESS_TOKEN_INVALID', 'The access token is invalid');
  }

  const amr = (claims as any).amr;
  return {
    sub: claims.sub,
    sid: claims.sid,
    ...(amr === 'password' || amr === 'social' || amr === 'sso' || amr === 'break_glass' ? { amr } : {}),
    typ: 'access',
  };
}

import type { AuthTokenPurpose, PrismaClient, User } from '@prisma/client';
import type { AppConfig } from '../../config/env';
import {
  buildEmailBrand,
  buildAccountDeletionScheduledEmail,
  buildEmailChangeEmail,
  buildPasswordChangedEmail,
  buildPasswordResetEmail,
  buildSecurityNotificationEmail,
  buildVerificationEmail,
  sendEmail,
} from '../../services/email';
import { assertPasswordLength, hashPassword, verifyPassword } from '../../services/password';
import { getPrismaClient } from '../../db/prisma';
import { AppError } from '../../utils/errors';
import { deriveKey, generateSecureToken, hashSecret, signValue } from '../../utils/crypto';
import { signAccessToken } from './access-token.service';
import { issueAuthToken, consumeAuthToken, invalidateAuthTokens } from './auth-token.service';
import {
  createSession,
  listActiveSessions,
  revokeAllSessions,
  revokeSession,
  rotateSession,
} from './session.service';
import { recordSecurityEvent, SecurityAction } from './security-events';
import { scheduledAccountDeletionAt } from './account-deletion.service';
import { ensurePersonalWorkspace } from '../workspaces/personal-workspace.service';
import { enqueueWorkspaceSeatReduction } from '../billing/membership-billing';
import { assertUserPasswordLoginAllowed, assertEmailNotInRequireSsoWorkspace } from '../sso/sso.service';
import { consumeOneTimeCode, issueOneTimeCode } from './one-time-code.service';
import type {
  AuthenticationResult,
  PublicUser,
  RequestContext,
  SessionSummary,
} from './auth.types';
import { createTwoFactorService, type TwoFactorService } from './two-factor.service';
import type {
  AccountDeleteInput,
  EmailChangeInput,
  LoginInput,
  PasswordChangeInput,
  PasswordResetInput,
  RegisterInput,
} from './auth.schemas';

/**
 * The Nexus account lifecycle.
 *
 * This service owns every decision about authentication state. Route handlers
 * only translate HTTP into service calls and back again.
 */

/**
 * A bcrypt hash of a random value. Comparing against it when an account does
 * not exist keeps the response time of a login attempt roughly constant, so
 * the endpoint cannot be used to enumerate registered addresses.
 */
const TIMING_EQUALIZER_HASH = '$2b$12$tQY.tSa8/ditlR/rZHqNUedooDRDLtvP5jx1YF0oCDy5Z2ojEpL1S';

export function toPublicUser(user: User): PublicUser {
  return {
    id: user.id,
    email: user.email,
    name: user.name,
    status: user.status,
    emailVerifiedAt: user.emailVerifiedAt,
    createdAt: user.createdAt,
  };
}

export interface AuthService {
  register(input: RegisterInput, ctx: RequestContext): Promise<{ user: PublicUser }>;
  verifyEmail(
    input: { email: string; code: string },
    ctx: RequestContext,
  ): Promise<{ user: PublicUser }>;
  resendVerification(input: { email: string }, ctx: RequestContext): Promise<void>;
  login(
    input: LoginInput,
    ctx: RequestContext,
  ): Promise<
    AuthenticationResult | { twoFactorRequired: true; challengeToken: string; expiresIn: number }
  >;
  ensureGoogleAccount(input: {
    subject: string;
    email: string;
    name: string;
  }): Promise<{ id: string }>;
  loginGoogleAccount(
    userId: string,
    ctx: RequestContext,
  ): Promise<
    AuthenticationResult | { twoFactorRequired: true; challengeToken: string; expiresIn: number }
  >;
  loginSsoAccount(
    userId: string,
    ctx: RequestContext,
    metadata?: { provider?: string; workspaceId?: string },
  ): Promise<
    AuthenticationResult | { twoFactorRequired: true; challengeToken: string; expiresIn: number }
  >;
  twoFactor: TwoFactorService;
  refresh(input: { refreshToken: string }, ctx: RequestContext): Promise<AuthenticationResult>;
  logout(input: { sessionId: string }, ctx: RequestContext): Promise<void>;
  logoutAll(input: { userId: string }, ctx: RequestContext): Promise<number>;
  listSessions(input: { userId: string; currentSessionId: string }): Promise<SessionSummary[]>;
  requestPasswordReset(input: { email: string }, ctx: RequestContext): Promise<void>;
  resetPassword(input: PasswordResetInput, ctx: RequestContext): Promise<void>;
  changePassword(
    input: PasswordChangeInput & { userId: string; sessionId: string },
    ctx: RequestContext,
  ): Promise<void>;
  requestEmailChange(
    input: EmailChangeInput & { userId: string },
    ctx: RequestContext,
  ): Promise<void>;
  confirmEmailChange(input: { token: string }, ctx: RequestContext): Promise<{ user: PublicUser }>;
  deactivateAccount(
    input: { userId: string; currentPassword: string },
    ctx: RequestContext,
  ): Promise<void>;
  reactivateAccount(input: LoginInput, ctx: RequestContext): Promise<{ user: PublicUser }>;
  deleteAccount(
    input: AccountDeleteInput & { userId: string },
    ctx: RequestContext,
  ): Promise<{ scheduledDeletionAt: Date }>;
}

export function createAuthService(config: AppConfig, prisma?: PrismaClient): AuthService {
  const client = prisma ?? getPrismaClient();

  async function sendVerificationCode(user: User, force: boolean): Promise<void> {
    const issued = await issueOneTimeCode(client, config, {
      userId: user.id,
      purpose: 'EMAIL_VERIFICATION',
      force,
    });
    if (!issued) return;
    await invalidateAuthTokens(client, { userId: user.id, purpose: 'EMAIL_VERIFICATION' });
    const result = await sendEmail(
      buildVerificationEmail({
        to: user.email,
        name: user.name,
        brand,
        code: issued.code,
        expiresAt: issued.expiresAt,
        idempotencyKey: `auth:email_verification:${user.id}:${issued.expiresAt.getTime()}`,
      }),
    );
    if (!result.accepted) console.error('email_verification_delivery_failed', { userId: user.id });
    if (config.nodeEnv === 'development')
      console.info('email_verification_code', { userId: user.id, code: issued.code });
  }

  async function sendPasswordResetCode(user: User): Promise<void> {
    const issued = await issueOneTimeCode(client, config, {
      userId: user.id,
      purpose: 'PASSWORD_RESET',
    });
    if (!issued) return;
    await invalidateAuthTokens(client, { userId: user.id, purpose: 'PASSWORD_RESET' });
    const result = await sendEmail(
      buildPasswordResetEmail({
        to: user.email,
        name: user.name,
        brand,
        code: issued.code,
        expiresAt: issued.expiresAt,
        idempotencyKey: `auth:password_reset:${user.id}:${issued.expiresAt.getTime()}`,
      }),
    );
    if (!result.accepted) console.error('password_reset_delivery_failed', { userId: user.id });
    if (config.nodeEnv === 'development')
      console.info('password_reset_code', { userId: user.id, code: issued.code });
  }
  const csrfKey = deriveKey(config.jwtAccessSecret, 'csrf');
  const brand = buildEmailBrand(config);

  function csrfTokenFor(sessionId: string): string {
    return signValue(csrfKey, sessionId);
  }

  function buildLink(path: string, token: string): string {
    const base = config.frontendUrl.replace(/\/+$/, '');
    return `${base}${path}?token=${encodeURIComponent(token)}`;
  }

  function buildPathLink(path: string): string {
    const base = config.frontendUrl.replace(/\/+$/, '');
    return `${base}${path}`;
  }

  async function findUserByEmail(email: string): Promise<User | null> {
    return client.user.findUnique({ where: { email } });
  }

  async function issueAndSend(
    input: {
      user: User;
      purpose: AuthTokenPurpose;
      ttlSeconds: number;
      targetEmail?: string | undefined;
    },
    buildMessage: (
      token: string,
      expiresAt: Date,
      tokenId: string,
    ) => Parameters<typeof sendEmail>[0],
  ): Promise<void> {
    const issued = await issueAuthToken(client, {
      userId: input.user.id,
      purpose: input.purpose,
      ttlSeconds: input.ttlSeconds,
      targetEmail: input.targetEmail,
    });

    const message = buildMessage(issued.token, issued.expiresAt, issued.id);

    // A delivery failure must not undo the account change that triggered it.
    const result = await sendEmail(message);

    if (!result.accepted) {
      // The token stays valid so the user can request a new link.
      await invalidateAuthTokens(client, {
        userId: input.user.id,
        purpose: input.purpose,
      });
    }
  }

  async function authenticateSession(
    session: { id: string; userId: string; expiresAt: Date; authMethod?: any },
    user: User,
    refreshToken: string,
  ): Promise<AuthenticationResult> {
    const authMethod = String((session as any).authMethod ?? 'PASSWORD').toLowerCase() as any;
    const { token: accessToken, expiresIn } = signAccessToken(config, {
      userId: session.userId,
      sessionId: session.id,
      authMethod,
    });

    return {
      user: toPublicUser(user),
      accessToken,
      tokenType: 'Bearer',
      expiresIn,
      csrfToken: csrfTokenFor(session.id),
      refreshToken,
      session: {
        id: session.id,
        expiresAt: session.expiresAt,
      },
    };
  }

  async function finishTwoFactorLogin(
    user: User,
    ctx: RequestContext,
  ): Promise<AuthenticationResult> {
    await assertEmailNotInRequireSsoWorkspace(client, user.email);
    const { session, refreshToken } = await createSession(client, {
      userId: user.id,
      ttlSeconds: config.refreshTokenTtlSeconds,
      authMethod: 'password',
      userAgent: ctx.userAgent,
      ip: ctx.ip,
    });
    await client.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } });
    await recordSecurityEvent(client, {
      action: SecurityAction.LoginSucceeded,
      targetType: 'Session',
      targetId: session.id,
      actorId: user.id,
      metadata: { userId: user.id, status: user.status, twoFactor: true },
      ip: ctx.ip,
      userAgent: ctx.userAgent,
    });
    return authenticateSession(session, user, refreshToken);
  }

  const twoFactor = createTwoFactorService(config, client, finishTwoFactorLogin);

  function assertUsableAccount(user: User): void {
    if (user.deletedAt) {
      throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deleted');
    }

    if (user.status === 'SUSPENDED') {
      throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
    }

    if (user.status === 'DEACTIVATED') {
      throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deactivated');
    }

    if (user.status === 'PENDING_DELETION') {
      throw new AppError(
        403,
        'ACCOUNT_PENDING_DELETION',
        'This account is being deleted and can no longer sign in.',
      );
    }
  }

  async function requirePassword(user: User, password: string): Promise<void> {
    const matches = await verifyPassword(password, user.passwordHash);

    if (!matches) {
      throw new AppError(401, 'INVALID_CREDENTIALS', 'The email address or password is incorrect');
    }
  }

  return {
    twoFactor,
    async ensureGoogleAccount(input): Promise<{ id: string }> {
      const identity = await client.externalIdentity.findUnique({
        where: {
          provider_providerSubjectId: { provider: 'google', providerSubjectId: input.subject },
        },
        include: { user: true },
      });
      if (identity) {
        assertUsableAccount(identity.user);
        return { id: identity.user.id };
      }

      const email = input.email.trim().toLowerCase();
      const existing = await findUserByEmail(email);
      if (existing) {
        throw new AppError(
          409,
          'GOOGLE_ACCOUNT_LINK_REQUIRED',
          'This email already has a Nexus account. Sign in and link Google from account settings.',
        );
      }

      const passwordHash = await hashPassword(generateSecureToken(), config.bcryptSaltRounds);
      try {
        const user = await client.$transaction(async (tx) => {
          const created = await tx.user.create({
            data: {
              email,
              name: input.name.trim().slice(0, 100) || email,
              passwordHash,
              status: 'ACTIVE',
              emailVerifiedAt: new Date(),
              externalIdentities: {
                create: { provider: 'google', providerSubjectId: input.subject },
              },
            },
          });
          await ensurePersonalWorkspace(tx, created);
          return created;
        });
        return { id: user.id };
      } catch (error) {
        if (
          typeof error === 'object' &&
          error !== null &&
          'code' in error &&
          error.code === 'P2002'
        ) {
          const raced = await client.externalIdentity.findUnique({
            where: {
              provider_providerSubjectId: { provider: 'google', providerSubjectId: input.subject },
            },
            select: { userId: true },
          });
          if (raced) return { id: raced.userId };
          const emailOwner = await findUserByEmail(email);
          if (emailOwner) {
            throw new AppError(
              409,
              'GOOGLE_ACCOUNT_LINK_REQUIRED',
              'Sign in and link Google from account settings',
            );
          }
        }
        throw error;
      }
    },
    async loginGoogleAccount(userId, ctx) {
      const user = await client.user.findUnique({ where: { id: userId } });
      if (!user)
        throw new AppError(
          401,
          'GOOGLE_IDENTITY_INVALID',
          'Google identity is no longer available',
        );
      assertUsableAccount(user);
      await assertEmailNotInRequireSsoWorkspace(client, user.email);
      if (user.twoFactorEnabled) return twoFactor.issueChallenge(user);

      const { session, refreshToken } = await createSession(client, {
        userId: user.id,
        ttlSeconds: config.refreshTokenTtlSeconds,
        authMethod: 'social',
        userAgent: ctx.userAgent,
        ip: ctx.ip,
      });
      await client.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } });
      await recordSecurityEvent(client, {
        action: SecurityAction.LoginSucceeded,
        targetType: 'Session',
        targetId: session.id,
        actorId: user.id,
        metadata: { userId: user.id, status: user.status, provider: 'google' },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
      return authenticateSession(session, user, refreshToken);
    },
    async loginSsoAccount(userId, ctx, metadata) {
      const user = await client.user.findUnique({ where: { id: userId } });
      if (!user) {
        throw new AppError(
          401,
          'SSO_IDENTITY_INVALID',
          'SSO identity is no longer available',
        );
      }
      assertUsableAccount(user);
      await assertEmailNotInRequireSsoWorkspace(client, user.email);
      if (user.twoFactorEnabled) return twoFactor.issueChallenge(user);

      const { session, refreshToken } = await createSession(client, {
        userId: user.id,
        ttlSeconds: config.refreshTokenTtlSeconds,
        authMethod: 'sso',
        userAgent: ctx.userAgent,
        ip: ctx.ip,
      });
      await client.user.update({ where: { id: user.id }, data: { lastLoginAt: new Date() } });
      await recordSecurityEvent(client, {
        action: SecurityAction.LoginSucceeded,
        targetType: 'Session',
        targetId: session.id,
        actorId: user.id,
        metadata: {
          userId: user.id,
          status: user.status,
          provider: metadata?.provider ?? 'sso',
          ...(metadata?.workspaceId ? { workspaceId: metadata.workspaceId } : {}),
        },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
      return authenticateSession(session, user, refreshToken);
    },
    async register(input: RegisterInput, ctx: RequestContext): Promise<{ user: PublicUser }> {
      const existing = await findUserByEmail(input.email);

      if (existing) {
        throw new AppError(
          409,
          'EMAIL_ALREADY_REGISTERED',
          'An account with this email address already exists',
        );
      }

      assertPasswordLength(input.password);

      const passwordHash = await hashPassword(input.password, config.bcryptSaltRounds);

      const user = await client.user.create({
        data: {
          email: input.email,
          name: input.name,
          passwordHash,
          status: 'PENDING_VERIFICATION',
          profile: {
            create: {
              timeZone: 'UTC',
              locale: 'en',
            },
          },
        },
      });

      await sendVerificationCode(user, true);

      // An invitation that was sent before the account existed is bound to
      // it now, so the same link lets the new account join the workspace.
      await client.invitation.updateMany({
        where: { email: user.email, status: 'PENDING', forUserId: null },
        data: { forUserId: user.id },
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.AccountRegistered,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        metadata: { status: user.status },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      return { user: toPublicUser(user) };
    },

    async verifyEmail(
      input: { email: string; code: string },
      ctx: RequestContext,
    ): Promise<{ user: PublicUser }> {
      const user = await client.$transaction(async (tx) => {
        const record = await consumeOneTimeCode(client, config, {
          email: input.email,
          code: input.code,
          purpose: 'EMAIL_VERIFICATION',
        });

        const verified = await tx.user.updateMany({
          where: {
            id: record.userId,
            deletedAt: null,
            status: { in: ['PENDING_VERIFICATION', 'ACTIVE'] },
          },
          data: {
            status: 'ACTIVE',
            emailVerifiedAt: new Date(),
          },
        });

        if (verified.count === 0) {
          const current = await tx.user.findUnique({ where: { id: record.userId } });

          if (!current || current.deletedAt) {
            throw new AppError(
              400,
              'TOKEN_INVALID',
              'This link is invalid or has already been used',
            );
          }

          if (current.status === 'SUSPENDED') {
            throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
          }

          if (current.status === 'DEACTIVATED' || current.status === 'PENDING_DELETION') {
            throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account is not active');
          }

          throw new AppError(409, 'ACCOUNT_NOT_VERIFIABLE', 'This account cannot be verified');
        }

        const verifiedUser = await tx.user.findUniqueOrThrow({ where: { id: record.userId } });
        await ensurePersonalWorkspace(tx, verifiedUser);

        return verifiedUser;
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.EmailVerified,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      return { user: toPublicUser(user) };
    },

    async resendVerification(input: { email: string }, ctx: RequestContext): Promise<void> {
      const user = await findUserByEmail(input.email);

      // The response never reveals whether the address is registered.
      if (!user || user.status !== 'PENDING_VERIFICATION' || user.deletedAt) {
        return;
      }

      await sendVerificationCode(user, false);

      await recordSecurityEvent(client, {
        action: SecurityAction.EmailVerificationRequested,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async login(
      input: LoginInput,
      ctx: RequestContext,
    ): Promise<
      AuthenticationResult | { twoFactorRequired: true; challengeToken: string; expiresIn: number }
    > {
      const user = await findUserByEmail(input.email);

      if (!user) {
        await verifyPassword(input.password, TIMING_EQUALIZER_HASH);

        await recordSecurityEvent(client, {
          action: SecurityAction.LoginFailed,
          targetType: 'User',
          targetId: 'unknown',
          metadata: { emailHash: hashSecret(input.email) },
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });

        throw new AppError(
          401,
          'INVALID_CREDENTIALS',
          'The email address or password is incorrect',
        );
      }

      const matches = await verifyPassword(input.password, user.passwordHash);

      if (!matches) {
        await recordSecurityEvent(client, {
          action: SecurityAction.LoginFailed,
          targetType: 'User',
          targetId: user.id,
          actorId: user.id,
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });

        throw new AppError(
          401,
          'INVALID_CREDENTIALS',
          'The email address or password is incorrect',
        );
      }

      assertUsableAccount(user);

      if (user.status === 'PENDING_VERIFICATION') await sendVerificationCode(user, false);

      await assertUserPasswordLoginAllowed(client, user.id);
      await assertEmailNotInRequireSsoWorkspace(client, user.email);

      if (user.twoFactorEnabled) {
        return twoFactor.issueChallenge(user);
      }

      const { session, refreshToken } = await createSession(client, {
        userId: user.id,
        ttlSeconds: config.refreshTokenTtlSeconds,
        authMethod: 'password',
        userAgent: ctx.userAgent,
        ip: ctx.ip,
      });

      await client.user.update({
        where: { id: user.id },
        data: { lastLoginAt: new Date() },
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.LoginSucceeded,
        targetType: 'Session',
        targetId: session.id,
        actorId: user.id,
        metadata: { userId: user.id, status: user.status },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      const result = await authenticateSession(session, user, refreshToken);

      return result;
    },

    async refresh(
      input: { refreshToken: string },
      ctx: RequestContext,
    ): Promise<AuthenticationResult> {
      const outcome = await rotateSession(client, {
        refreshToken: input.refreshToken,
        userAgent: ctx.userAgent,
        ip: ctx.ip,
      });

      if (outcome.kind === 'reused') {
        const revoked = await revokeAllSessions(client, {
          userId: outcome.session.userId,
          reason: 'REFRESH_TOKEN_REUSE',
        });
        await twoFactor.revokeChallenges(outcome.session.userId);

        await recordSecurityEvent(client, {
          action: SecurityAction.SessionReuseDetected,
          targetType: 'Session',
          targetId: outcome.session.id,
          actorId: outcome.session.userId,
          metadata: { revokedSessions: revoked },
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });

        throw new AppError(
          401,
          'SESSION_REUSE_DETECTED',
          'Your session was ended for security reasons. Please sign in again.',
        );
      }

      const user = await client.user.findUnique({ where: { id: outcome.session.userId } });

      if (!user) {
        throw new AppError(401, 'REFRESH_TOKEN_INVALID', 'Your session is no longer valid');
      }

      assertUsableAccount(user);

      await recordSecurityEvent(client, {
        action: SecurityAction.SessionRefreshed,
        targetType: 'Session',
        targetId: outcome.session.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      const result = await authenticateSession(outcome.session, user, outcome.refreshToken);

      return result;
    },

    async logout(input: { sessionId: string }, ctx: RequestContext): Promise<void> {
      await revokeSession(client, input.sessionId, 'LOGOUT');

      await recordSecurityEvent(client, {
        action: SecurityAction.LoggedOut,
        targetType: 'Session',
        targetId: input.sessionId,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async logoutAll(input: { userId: string }, ctx: RequestContext): Promise<number> {
      await twoFactor.revokeChallenges(input.userId);
      const revoked = await revokeAllSessions(client, {
        userId: input.userId,
        reason: 'LOGOUT_ALL',
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.LoggedOutAll,
        targetType: 'User',
        targetId: input.userId,
        actorId: input.userId,
        metadata: { revokedSessions: revoked },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      return revoked;
    },

    async listSessions(input: {
      userId: string;
      currentSessionId: string;
    }): Promise<SessionSummary[]> {
      const sessions = await listActiveSessions(client, {
        userId: input.userId,
        currentSessionId: input.currentSessionId,
      });

      return sessions.map((session) => ({
        id: session.id,
        userAgent: session.userAgent,
        ip: session.ip,
        createdAt: session.createdAt,
        lastUsedAt: session.lastUsedAt,
        expiresAt: session.expiresAt,
        current: session.id === input.currentSessionId,
      }));
    },

    async requestPasswordReset(input: { email: string }, ctx: RequestContext): Promise<void> {
      const user = await findUserByEmail(input.email);

      // The response never reveals whether the address is registered.
      if (
        !user ||
        user.deletedAt ||
        user.status === 'DEACTIVATED' ||
        user.status === 'PENDING_DELETION'
      ) {
        return;
      }

      await assertUserPasswordLoginAllowed(client, user.id);
      await assertEmailNotInRequireSsoWorkspace(client, user.email);

      await sendPasswordResetCode(user);

      await recordSecurityEvent(client, {
        action: SecurityAction.PasswordResetRequested,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async resetPassword(input: PasswordResetInput, ctx: RequestContext): Promise<void> {
      const record = await consumeOneTimeCode(client, config, {
        email: input.email,
        code: input.code,
        purpose: 'PASSWORD_RESET',
      });

      const account = await client.user.findUnique({ where: { id: record.userId } });

      if (!account || account.deletedAt) {
        throw new AppError(400, 'TOKEN_INVALID', 'This link is invalid or has already been used');
      }

      if (account.status === 'PENDING_DELETION') {
        throw new AppError(
          403,
          'ACCOUNT_PENDING_DELETION',
          'Recover the account before changing its password',
        );
      }

      if (account.status === 'DEACTIVATED') {
        throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deactivated');
      }

      await assertUserPasswordLoginAllowed(client, account.id);
      await assertEmailNotInRequireSsoWorkspace(client, account.email);

      assertPasswordLength(input.newPassword);

      await twoFactor.revokeChallenges(record.userId);

      const passwordHash = await hashPassword(input.newPassword, config.bcryptSaltRounds);

      await client.user.update({
        where: { id: record.userId },
        data: { passwordHash },
      });

      // A reset invalidates every existing session.
      const revoked = await revokeAllSessions(client, {
        userId: record.userId,
        reason: 'PASSWORD_RESET',
      });

      await invalidateAuthTokens(client, {
        userId: record.userId,
        purpose: 'PASSWORD_RESET',
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.PasswordReset,
        targetType: 'User',
        targetId: record.userId,
        actorId: record.userId,
        metadata: { revokedSessions: revoked },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async changePassword(
      input: PasswordChangeInput & { userId: string; sessionId: string },
      ctx: RequestContext,
    ): Promise<void> {
      const user = await client.user.findUnique({ where: { id: input.userId } });

      if (!user) {
        throw new AppError(404, 'USER_NOT_FOUND', 'The requested account was not found');
      }

      await requirePassword(user, input.currentPassword);

      await assertUserPasswordLoginAllowed(client, user.id);

      if (await verifyPassword(input.newPassword, user.passwordHash)) {
        throw new AppError(
          400,
          'PASSWORD_UNCHANGED',
          'The new password must be different from the current password',
        );
      }

      assertPasswordLength(input.newPassword);

      await twoFactor.revokeChallenges(user.id);

      const passwordHash = await hashPassword(input.newPassword, config.bcryptSaltRounds);

      await client.user.update({
        where: { id: user.id },
        data: { passwordHash },
      });

      // Every other device is signed out. The current session stays active.
      const revoked = await revokeAllSessions(client, {
        userId: user.id,
        reason: 'PASSWORD_CHANGED',
        exceptSessionId: input.sessionId,
      });

      const changedAt = new Date();

      await sendEmail(
        buildPasswordChangedEmail({
          to: user.email,
          name: user.name,
          brand,
          changedAt,
          resetUrl: buildPathLink(config.authPasswordResetLinkPath),
          idempotencyKey: `auth:password_changed:${user.id}:${changedAt.getTime()}`,
        }),
      );

      await recordSecurityEvent(client, {
        action: SecurityAction.PasswordChanged,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        metadata: { revokedSessions: revoked },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async requestEmailChange(
      input: EmailChangeInput & { userId: string },
      ctx: RequestContext,
    ): Promise<void> {
      const user = await client.user.findUnique({ where: { id: input.userId } });

      if (!user) {
        throw new AppError(404, 'USER_NOT_FOUND', 'The requested account was not found');
      }

      await requirePassword(user, input.currentPassword);

      await twoFactor.revokeChallenges(user.id);

      if (input.email === user.email) {
        throw new AppError(
          400,
          'EMAIL_UNCHANGED',
          'The new email address must be different from the current one',
        );
      }

      const existing = await findUserByEmail(input.email);

      if (existing) {
        throw new AppError(
          409,
          'EMAIL_ALREADY_REGISTERED',
          'An account with this email address already exists',
        );
      }

      await issueAndSend(
        {
          user,
          purpose: 'EMAIL_CHANGE',
          ttlSeconds: config.emailChangeTokenTtlSeconds,
          targetEmail: input.email,
        },
        (token, expiresAt, tokenId) =>
          buildEmailChangeEmail({
            to: input.email,
            name: user.name,
            brand,
            verificationUrl: buildLink(config.authEmailChangeLinkPath, token),
            expiresAt,
            newEmail: input.email,
            idempotencyKey: `auth:email_change:${tokenId}`,
          }),
      );

      // The current address is notified so the change is not a surprise.
      await sendEmail(
        buildSecurityNotificationEmail({
          to: user.email,
          name: user.name,
          brand,
          subject: `A ${brand.appName} email address change was requested`,
          detail: `A request was made to change the email address on your ${brand.appName} account to ${input.email}. If this was not you, change your password immediately.`,
          actionUrl: buildPathLink(config.authPasswordResetLinkPath),
          actionLabel: 'Reset your password',
          idempotencyKey: `auth:email_change_notice:${user.id}:${hashSecret(input.email)}`,
        }),
      );

      await recordSecurityEvent(client, {
        action: SecurityAction.EmailChangeRequested,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        metadata: { targetEmailHash: hashSecret(input.email) },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async confirmEmailChange(
      input: { token: string },
      ctx: RequestContext,
    ): Promise<{ user: PublicUser }> {
      const record = await consumeAuthToken(client, {
        token: input.token,
        purpose: 'EMAIL_CHANGE',
      });

      if (!record.targetEmail) {
        throw new AppError(400, 'TOKEN_INVALID', 'This link is invalid or has already been used');
      }

      const current = await client.user.findUnique({ where: { id: record.userId } });

      if (!current || current.deletedAt) {
        throw new AppError(400, 'TOKEN_INVALID', 'This link is invalid or has already been used');
      }

      if (current.status === 'SUSPENDED') {
        throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
      }

      if (current.status === 'DEACTIVATED' || current.status === 'PENDING_DELETION') {
        throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deactivated');
      }

      const existing = await findUserByEmail(record.targetEmail);

      if (existing && existing.id !== record.userId) {
        throw new AppError(
          409,
          'EMAIL_ALREADY_REGISTERED',
          'An account with this email address already exists',
        );
      }

      const changed = await client.user.updateMany({
        where: {
          id: record.userId,
          deletedAt: null,
          status: { in: ['PENDING_VERIFICATION', 'ACTIVE'] },
        },
        data: {
          email: record.targetEmail,
          emailVerifiedAt: new Date(),
          status: 'ACTIVE',
        },
      });

      if (changed.count === 0) {
        const latest = await client.user.findUnique({ where: { id: record.userId } });

        if (!latest || latest.deletedAt) {
          throw new AppError(400, 'TOKEN_INVALID', 'This link is invalid or has already been used');
        }

        if (latest.status === 'SUSPENDED') {
          throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
        }

        if (latest.status === 'DEACTIVATED' || latest.status === 'PENDING_DELETION') {
          throw new AppError(403, 'ACCOUNT_DEACTIVATED', 'This account has been deactivated');
        }

        throw new AppError(409, 'ACCOUNT_NOT_CHANGEABLE', 'This account cannot be changed');
      }

      const user = await client.user.findUniqueOrThrow({ where: { id: record.userId } });

      await recordSecurityEvent(client, {
        action: SecurityAction.EmailChanged,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      return { user: toPublicUser(user) };
    },

    async deactivateAccount(
      input: { userId: string; currentPassword: string },
      ctx: RequestContext,
    ): Promise<void> {
      const user = await client.user.findUnique({ where: { id: input.userId } });

      if (!user) {
        throw new AppError(404, 'USER_NOT_FOUND', 'The requested account was not found');
      }

      await requirePassword(user, input.currentPassword);

      await twoFactor.revokeChallenges(user.id);

      const deactivatedAt = new Date();

      await client.$transaction(async (tx) => {
        await tx.user.update({
          where: { id: user.id },
          data: { status: 'DEACTIVATED' },
        });

        await tx.session.updateMany({
          where: { userId: user.id, revokedAt: null },
          data: { revokedAt: deactivatedAt, revokedReason: 'ACCOUNT_DEACTIVATED' },
        });

        await tx.authToken.updateMany({
          where: { userId: user.id, usedAt: null },
          data: { usedAt: deactivatedAt },
        });
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.AccountDeactivated,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });
    },

    async reactivateAccount(input: LoginInput, ctx: RequestContext): Promise<{ user: PublicUser }> {
      const user = await findUserByEmail(input.email);

      async function recordReactivationFailure(userId: string, reason: string): Promise<void> {
        await recordSecurityEvent(client, {
          action: SecurityAction.AccountReactivationFailed,
          targetType: 'User',
          targetId: userId,
          actorId: userId,
          metadata: { reason },
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });
      }

      if (!user || user.deletedAt) {
        await verifyPassword(input.password, TIMING_EQUALIZER_HASH);

        await recordSecurityEvent(client, {
          action: SecurityAction.AccountReactivationFailed,
          targetType: 'User',
          targetId: user?.id ?? 'unknown',
          ...(user ? { actorId: user.id } : {}),
          metadata: { emailHash: hashSecret(input.email), reason: 'INVALID_CREDENTIALS' },
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });

        throw new AppError(
          401,
          'INVALID_CREDENTIALS',
          'The email address or password is incorrect',
        );
      }

      const matches = await verifyPassword(input.password, user.passwordHash);

      if (!matches) {
        await recordSecurityEvent(client, {
          action: SecurityAction.AccountReactivationFailed,
          targetType: 'User',
          targetId: user.id,
          actorId: user.id,
          metadata: { reason: 'INVALID_CREDENTIALS' },
          ip: ctx.ip,
          userAgent: ctx.userAgent,
        });

        throw new AppError(
          401,
          'INVALID_CREDENTIALS',
          'The email address or password is incorrect',
        );
      }

      await assertUserPasswordLoginAllowed(client, user.id);

      if (user.status === 'SUSPENDED') {
        await recordReactivationFailure(user.id, 'ACCOUNT_SUSPENDED');
        throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
      }

      if (
        user.status === 'PENDING_DELETION' &&
        (!user.scheduledDeletionAt || user.scheduledDeletionAt <= new Date())
      ) {
        await recordReactivationFailure(user.id, 'DELETION_RECOVERY_PERIOD_EXPIRED');
        throw new AppError(
          409,
          'DELETION_RECOVERY_PERIOD_EXPIRED',
          'The account recovery period has expired',
        );
      }

      if (user.status === 'ACTIVE') {
        await recordReactivationFailure(user.id, 'ACCOUNT_ALREADY_ACTIVE');
        throw new AppError(409, 'ACCOUNT_ALREADY_ACTIVE', 'This account is already active');
      }

      if (user.status !== 'DEACTIVATED' && user.status !== 'PENDING_DELETION') {
        await recordReactivationFailure(user.id, 'ACCOUNT_NOT_DEACTIVATED');
        throw new AppError(409, 'ACCOUNT_NOT_DEACTIVATED', 'This account is not deactivated');
      }

      const nextStatus = user.emailVerifiedAt ? 'ACTIVE' : 'PENDING_VERIFICATION';

      const reactivated = await client.$transaction(async (tx) => {
        const updated = await tx.user.updateMany({
          where: {
            id: user.id,
            status: user.status,
            deletedAt: null,
            ...(user.status === 'PENDING_DELETION'
              ? { scheduledDeletionAt: { gt: new Date() } }
              : {}),
          },
          data: {
            status: nextStatus,
            deletionRequestedAt: null,
            scheduledDeletionAt: null,
          },
        });

        if (updated.count === 0) {
          return null;
        }

        await tx.session.updateMany({
          where: { userId: user.id, revokedAt: null },
          data: { revokedAt: new Date(), revokedReason: 'ACCOUNT_REACTIVATED' },
        });

        await tx.authToken.updateMany({
          where: { userId: user.id, usedAt: null },
          data: { usedAt: new Date() },
        });

        const restored = await tx.user.findUniqueOrThrow({ where: { id: user.id } });

        if (restored.status === 'ACTIVE') {
          await ensurePersonalWorkspace(tx, restored);
          if (user.status === 'PENDING_DELETION') {
            await tx.workspace.updateMany({
              where: { ownerId: restored.id, deletionSuspendedAt: { not: null }, deletedAt: null },
              data: { status: 'ACTIVE', deletionSuspendedAt: null },
            });
            await tx.billingCancellation.updateMany({
              where: {
                workspace: { ownerId: restored.id },
                status: { in: ['PENDING', 'PROCESSING'] },
              },
              data: { status: 'CANCELLED', lastError: null },
            });
          }
          const memberships = await tx.workspaceMembership.findMany({
            where: { userId: restored.id, status: 'ACTIVE' },
            select: { workspaceId: true },
          });
          for (const workspaceId of new Set(memberships.map(({ workspaceId }) => workspaceId))) {
            await enqueueWorkspaceSeatReduction(tx, workspaceId);
          }
        }

        return restored;
      });

      if (!reactivated) {
        await recordReactivationFailure(user.id, 'ACCOUNT_NOT_REACTIVATABLE');
        throw new AppError(
          409,
          'ACCOUNT_NOT_REACTIVATABLE',
          'This account can no longer be reactivated',
        );
      }

      if (reactivated.status === 'PENDING_VERIFICATION') {
        await sendVerificationCode(reactivated, true);
      }

      await recordSecurityEvent(client, {
        action: SecurityAction.AccountReactivated,
        targetType: 'User',
        targetId: reactivated.id,
        actorId: reactivated.id,
        metadata: {
          status: reactivated.status,
          verificationRequired: reactivated.status === 'PENDING_VERIFICATION',
        },
        ip: ctx.ip,
        userAgent: ctx.userAgent,
      });

      return { user: toPublicUser(reactivated) };
    },

    async deleteAccount(
      input: AccountDeleteInput & { userId: string },
      _ctx: RequestContext,
    ): Promise<{ scheduledDeletionAt: Date }> {
      const user = await client.user.findUnique({ where: { id: input.userId } });

      if (!user) {
        throw new AppError(404, 'USER_NOT_FOUND', 'The requested account was not found');
      }

      await requirePassword(user, input.currentPassword);

      await twoFactor.revokeChallenges(user.id);

      if (input.confirmation.toLowerCase() !== user.email.toLowerCase()) {
        throw new AppError(
          400,
          'CONFIRMATION_MISMATCH',
          'Type your email address exactly to confirm the deletion',
        );
      }

      const requestedAt = new Date();
      const scheduledDeletionAt = scheduledAccountDeletionAt(requestedAt);

      await client.$transaction(async (tx) => {
        const [lockedUser] = await tx.$queryRaw<
          Array<{ status: string; deletedAt: Date | null }>
        >`SELECT "status"::text AS "status", "deletedAt"
          FROM "User"
          WHERE "id" = ${user.id}
          FOR UPDATE`;

        if (!lockedUser) {
          throw new AppError(404, 'USER_NOT_FOUND', 'The requested account was not found');
        }

        if (lockedUser.deletedAt || lockedUser.status === 'DEACTIVATED') {
          throw new AppError(
            409,
            'ACCOUNT_ALREADY_DELETED',
            'This account has already been deleted or deactivated',
          );
        }

        if (lockedUser.status === 'PENDING_DELETION') {
          throw new AppError(
            409,
            'ACCOUNT_DELETION_ALREADY_REQUESTED',
            'This account is already scheduled for deletion',
          );
        }

        if (lockedUser.status === 'SUSPENDED') {
          throw new AppError(403, 'ACCOUNT_SUSPENDED', 'This account has been suspended');
        }

        const administrativeRoles = [
          'COMPANY_OWNER',
          'COMPANY_ADMIN',
          'INSTITUTION_OWNER',
          'INSTITUTION_ADMIN',
        ] as const;
        const administrativeMemberships = await tx.workspaceMembership.findMany({
          where: {
            userId: user.id,
            status: 'ACTIVE',
            workspace: {
              type: { in: ['COMPANY', 'INSTITUTION'] },
              status: 'ACTIVE',
            },
          },
          select: {
            workspaceId: true,
            role: true,
            organizationRole: true,
            workspace: { select: { ownerId: true } },
          },
        });
        for (const membership of administrativeMemberships) {
          const isAdministrator =
            membership.role === 'PROJECT_MANAGER' ||
            membership.role === 'OWNER' ||
            administrativeRoles.includes(
              membership.organizationRole as (typeof administrativeRoles)[number],
            );
          // An owner may schedule deletion; the owned workspace is suspended
          // until a successor accepts the transfer. A non-owner administrator
          // cannot leave an active organization without another active owner
          // or administrator who can manage that suspended workspace.
          if (!isAdministrator || membership.workspace.ownerId === user.id) continue;

          const activeSuccessors = await tx.workspaceMembership.count({
            where: {
              workspaceId: membership.workspaceId,
              userId: { not: user.id },
              status: 'ACTIVE',
              user: { status: 'ACTIVE', deletedAt: null },
              OR: [
                { role: { in: ['OWNER', 'PROJECT_MANAGER'] } },
                { organizationRole: { in: [...administrativeRoles] } },
              ],
            },
          });
          if (activeSuccessors === 0) {
            throw new AppError(
              409,
              'LAST_ORGANIZATION_ADMIN',
              'Another active owner or administrator must remain in the organization',
            );
          }
        }

        await tx.session.updateMany({
          where: { userId: user.id, revokedAt: null },
          data: { revokedAt: requestedAt, revokedReason: 'ACCOUNT_PENDING_DELETION' },
        });
        await tx.authToken.updateMany({
          where: { userId: user.id, usedAt: null },
          data: { usedAt: requestedAt },
        });
        await tx.user.update({
          where: { id: user.id },
          data: {
            status: 'PENDING_DELETION',
            deletionRequestedAt: requestedAt,
            scheduledDeletionAt,
          },
        });

        const ownedWorkspaces = await tx.workspace.findMany({
          where: { ownerId: user.id, deletedAt: null, status: 'ACTIVE' },
          select: { id: true, subscription: { select: { id: true, status: true } } },
        });
        await tx.workspace.updateMany({
          where: { ownerId: user.id, deletedAt: null, status: 'ACTIVE' },
          data: { status: 'SUSPENDED', deletionSuspendedAt: requestedAt },
        });
        await tx.workspaceOwnershipTransfer.updateMany({
          where: { initiatedById: user.id, status: 'PENDING' },
          data: { expiresAt: scheduledDeletionAt },
        });
        for (const workspace of ownedWorkspaces) {
          if (!workspace.subscription || workspace.subscription.status === 'CANCELLED') continue;
          await tx.billingCancellation.upsert({
            where: { workspaceId: workspace.id },
            create: {
              workspaceId: workspace.id,
              status: 'PENDING',
              nextAttemptAt: scheduledDeletionAt,
            },
            update: {
              status: 'PENDING',
              attempts: 0,
              nextAttemptAt: scheduledDeletionAt,
              lastError: null,
            },
          });
        }
      });

      await recordSecurityEvent(client, {
        action: SecurityAction.AccountDeletionRequested,
        targetType: 'User',
        targetId: user.id,
        actorId: user.id,
        metadata: { scheduledDeletionAt: scheduledDeletionAt.toISOString() },
      });
      await sendEmail(
        buildAccountDeletionScheduledEmail({
          to: user.email,
          name: user.name,
          brand,
          scheduledDeletionAt,
          idempotencyKey: `auth:deletion_requested:${user.id}:${requestedAt.getTime()}`,
        }),
      );

      return { scheduledDeletionAt };
    },
  };
}

export type { AuthenticationResult };

import type { PrismaClient, Session } from '@prisma/client';
import { AppError } from '../../utils/errors';
import { generateSecureToken, hashSecret } from '../../utils/crypto';

/**
 * Browser sessions.
 *
 * A session is a row in PostgreSQL that holds the hash of the current refresh
 * token. The refresh token itself is an opaque random value handed to the
 * client in an httpOnly cookie; only its digest is stored.
 *
 * Refresh tokens rotate on every use. The digest of the previous token is
 * kept for one rotation so that a replayed token can be recognised and the
 * whole session family can be revoked.
 */

export type SessionAuthMethod = 'password' | 'social' | 'sso' | 'break_glass';

export interface IssuedSession {
  session: Session;
  refreshToken: string;
}

export async function createSession(
  prisma: PrismaClient,
  input: {
    userId: string;
    ttlSeconds: number;
    authMethod: SessionAuthMethod;
    authMethodExpiresAt?: Date | undefined;
    userAgent?: string | undefined;
    ip?: string | undefined;
  },
): Promise<IssuedSession> {
  const refreshToken = generateSecureToken();
  const expiresAt = new Date(Date.now() + input.ttlSeconds * 1_000);

  const session = await prisma.session.create({
    data: {
      userId: input.userId,
      refreshTokenHash: hashSecret(refreshToken),
      authMethod: input.authMethod.toUpperCase() as any,
      ...(input.authMethodExpiresAt ? { authMethodExpiresAt: input.authMethodExpiresAt } : {}),
      expiresAt,
      lastUsedAt: new Date(),
      ...(input.userAgent ? { userAgent: input.userAgent.slice(0, 512) } : {}),
      ...(input.ip ? { ip: input.ip.slice(0, 128) } : {}),
    },
  });

  return { session, refreshToken };
}

export type RotationOutcome =
  | { kind: 'rotated'; session: Session; refreshToken: string }
  | { kind: 'reused'; session: Session };

/**
 * Rotates the refresh token of an active session.
 *
 * Presenting a token that was already rotated is treated as a compromise:
 * every session belonging to the user is revoked.
 */
export async function rotateSession(
  prisma: PrismaClient,
  input: {
    refreshToken: string;
    userAgent?: string | undefined;
    ip?: string | undefined;
  },
): Promise<RotationOutcome> {
  const tokenHash = hashSecret(input.refreshToken);

  const current = await prisma.session.findUnique({
    where: { refreshTokenHash: tokenHash },
  });

  if (!current) {
    const previous = await prisma.session.findUnique({
      where: { previousRefreshTokenHash: tokenHash },
    });

    if (previous) {
      return { kind: 'reused', session: previous };
    }

    throw new AppError(401, 'REFRESH_TOKEN_INVALID', 'Your session is no longer valid');
  }

  if (current.revokedAt) {
    return { kind: 'reused', session: current };
  }

  if (current.expiresAt.getTime() <= Date.now()) {
    throw new AppError(401, 'SESSION_EXPIRED', 'Your session has expired. Please sign in again.');
  }

  const nextRefreshToken = generateSecureToken();

  // Compare-and-swap the exact refresh state that was read above. PostgreSQL
  // rechecks these predicates after waiting for a concurrent row update, so
  // only one request can consume this token hash.
  const rotation = await prisma.session.updateMany({
    where: {
      id: current.id,
      refreshTokenHash: tokenHash,
      revokedAt: null,
      expiresAt: { gt: new Date() },
    },
    data: {
      refreshTokenHash: hashSecret(nextRefreshToken),
      previousRefreshTokenHash: tokenHash,
      lastUsedAt: new Date(),
      ...(input.userAgent ? { userAgent: input.userAgent.slice(0, 512) } : {}),
      ...(input.ip ? { ip: input.ip.slice(0, 128) } : {}),
    },
  });

  if (rotation.count !== 1) {
    // A request that lost the compare-and-swap may have presented a token
    // that is now recorded as the previous token. Preserve the established
    // reuse-detection policy; otherwise report the current session state.
    const previous = await prisma.session.findUnique({
      where: { previousRefreshTokenHash: tokenHash },
    });

    if (previous) {
      return { kind: 'reused', session: previous };
    }

    const latest = await prisma.session.findUnique({ where: { id: current.id } });

    if (latest?.revokedAt) {
      return { kind: 'reused', session: latest };
    }

    if (latest && latest.expiresAt.getTime() <= Date.now()) {
      throw new AppError(401, 'SESSION_EXPIRED', 'Your session has expired. Please sign in again.');
    }

    throw new AppError(401, 'REFRESH_TOKEN_INVALID', 'Your session is no longer valid');
  }

  const session = await prisma.session.findUnique({
    where: { refreshTokenHash: hashSecret(nextRefreshToken) },
  });

  if (!session) {
    // Do not return the generated token unless its state is visible as
    // persisted. A database failure here rejects the request.
    throw new AppError(401, 'REFRESH_TOKEN_INVALID', 'Your session is no longer valid');
  }

  return { kind: 'rotated', session, refreshToken: nextRefreshToken };
}

export async function revokeSession(
  prisma: PrismaClient,
  sessionId: string,
  reason: string,
): Promise<void> {
  await prisma.session.updateMany({
    where: { id: sessionId, revokedAt: null },
    data: { revokedAt: new Date(), revokedReason: reason },
  });
}

export async function revokeAllSessions(
  prisma: PrismaClient,
  input: { userId: string; reason: string; exceptSessionId?: string | undefined },
): Promise<number> {
  const result = await prisma.session.updateMany({
    where: {
      userId: input.userId,
      revokedAt: null,
      ...(input.exceptSessionId ? { id: { not: input.exceptSessionId } } : {}),
    },
    data: { revokedAt: new Date(), revokedReason: input.reason },
  });

  return result.count;
}

export async function listActiveSessions(
  prisma: PrismaClient,
  input: { userId: string; currentSessionId?: string | undefined },
): Promise<Session[]> {
  return prisma.session.findMany({
    where: {
      userId: input.userId,
      revokedAt: null,
      expiresAt: { gt: new Date() },
    },
    orderBy: { createdAt: 'desc' },
  });
}

export async function findActiveSession(
  prisma: PrismaClient,
  sessionId: string,
): Promise<Session | null> {
  const session = await prisma.session.findUnique({
    where: { id: sessionId },
  });

  if (!session || session.revokedAt || session.expiresAt.getTime() <= Date.now()) {
    return null;
  }

  return session;
}

/**
 * Finds the session that a refresh token belongs to, whether or not it is
 * still active.
 *
 * Used to resolve the session for CSRF validation and for logout, where a
 * revoked session still has to be identifiable.
 */
export async function findSessionByRefreshToken(
  prisma: PrismaClient,
  refreshToken: string,
): Promise<Session | null> {
  const tokenHash = hashSecret(refreshToken);

  const session = await prisma.session.findUnique({
    where: { refreshTokenHash: tokenHash },
  });

  if (session) {
    return session;
  }

  return prisma.session.findUnique({
    where: { previousRefreshTokenHash: tokenHash },
  });
}

import type { PrismaClient, Workspace, WorkspaceMembership, WorkspaceRole } from '@prisma/client';
import { effectiveWorkspaceRole, isOrganizationRoleForWorkspace } from './organization-role';
import { AppError } from '../../utils/errors';

/**
 * Workspace-level authorization policy.
 *
 * This module is the single authoritative source for what each workspace role
 * is allowed to do.  Phase 5 shipped an inline version inside
 * `src/modules/workspaces/authorization.ts`; Phase 6 replaces those inline
 * checks with this centralized module and re-exports the same surface from
 * the workspaces module for backward compatibility.
 *
 * Design decisions
 * ----------------
 * - Every check is made against the membership row that lives in the
 *   database.  A role value that a client sends in a request body is never
 *   trusted.
 * - A workspace that does not exist is reported as NOT_FOUND; a workspace
 *   the caller does not belong to is reported as ACCESS_DENIED.  The two
 *   codes are kept distinct so a member can learn that a workspace exists
 *   while an outsider cannot use the endpoint to probe for identifiers.
 * - Ownership transfer is gated on `workspace:transfer_ownership` and is
 *   only available to the current owner.
 * - A member cannot remove themselves when they are the last
 *   OWNER, which would leave the workspace permanently ownerless.
 */

// ---------------------------------------------------------------------------
// Capability constants
// ---------------------------------------------------------------------------

export const WorkspaceCapability = {
  // Basic reads
  ViewWorkspace: 'workspace:view',
  ViewMembers: 'member:view',
  // Workspace mutations
  UpdateWorkspace: 'workspace:update',
  ArchiveWorkspace: 'workspace:archive',
  DeleteWorkspace: 'workspace:delete',
  // Membership management
  ManageMembers: 'member:manage',
  // Invitation management
  ViewInvitations: 'invitation:view',
  ManageInvitations: 'invitation:manage',
  // Join requests (discovery is public to authenticated accounts)
  ViewJoinRequests: 'join_request:view',
  ManageJoinRequests: 'join_request:manage',
  // Ownership transfer (owner only)
  TransferOwnership: 'workspace:transfer_ownership',
} as const;

export type WorkspaceCapabilityValue =
  (typeof WorkspaceCapability)[keyof typeof WorkspaceCapability];

// ---------------------------------------------------------------------------
// Role → capability matrix
// ---------------------------------------------------------------------------

/**
 * The full workspace permission matrix.
 *
 * Each entry lists the roles that hold the capability.  The matrix is
 * evaluated by `workspaceRoleCan`, which is the only place where a role is
 * compared to a capability.
 */
const WORKSPACE_CAPABILITIES: Record<WorkspaceCapabilityValue, readonly WorkspaceRole[]> = {
  'workspace:view': ['OWNER', 'PROJECT_MANAGER', 'MEMBER', 'COLLABORATOR', 'VIEWER'],
  'workspace:update': ['OWNER', 'PROJECT_MANAGER'],
  'workspace:archive': ['OWNER'],
  'workspace:delete': ['OWNER'],
  'workspace:transfer_ownership': ['OWNER'],
  'member:view': ['OWNER', 'PROJECT_MANAGER', 'MEMBER', 'COLLABORATOR', 'VIEWER'],
  'member:manage': ['OWNER', 'PROJECT_MANAGER'],
  'invitation:view': ['OWNER', 'PROJECT_MANAGER'],
  'invitation:manage': ['OWNER', 'PROJECT_MANAGER'],
  'join_request:view': ['OWNER', 'PROJECT_MANAGER'],
  'join_request:manage': ['OWNER', 'PROJECT_MANAGER'],
};

/**
 * Returns whether the given workspace role has the given capability.
 */
export function workspaceRoleCan(
  role: WorkspaceRole,
  capability: WorkspaceCapabilityValue,
): boolean {
  return WORKSPACE_CAPABILITIES[capability].includes(role);
}

// ---------------------------------------------------------------------------
// Access guard
// ---------------------------------------------------------------------------

export interface WorkspaceAccess {
  workspace: Workspace;
  membership: WorkspaceMembership;
  effectiveRole: WorkspaceRole;
}

/**
 * Loads the workspace and proves the caller is authorised to use it.
 *
 * Throws `AppError` with an appropriate status and code when the workspace
 * does not exist, the caller is not a member, or the caller's role does not
 * hold the requested capability.
 */
export async function requireWorkspaceAccess(
  client: PrismaClient,
  input: {
    userId: string;
    workspaceId: string;
    capability: WorkspaceCapabilityValue;
    allowArchived?: boolean;
    auth?: { authMethod?: string; sessionId?: string };
  },
): Promise<WorkspaceAccess> {
  const workspace = await client.workspace.findFirst({
    where: { id: input.workspaceId, deletedAt: null },
  });

  if (!workspace) {
    throw new AppError(404, 'WORKSPACE_NOT_FOUND', 'That workspace does not exist');
  }

  if (workspace.status === 'ARCHIVED' && !input.allowArchived) {
    throw new AppError(404, 'WORKSPACE_NOT_FOUND', 'That workspace does not exist');
  }

  if (workspace.status === 'SUSPENDED') {
    throw new AppError(403, 'WORKSPACE_SUSPENDED', 'This workspace is suspended');
  }

  const membership = await client.workspaceMembership.findUnique({
    where: { workspaceId_userId: { workspaceId: workspace.id, userId: input.userId } },
  });

  if (!membership) {
    throw new AppError(403, 'WORKSPACE_ACCESS_DENIED', 'You are not a member of this workspace');
  }

  // A suspended membership keeps the row (and its history) but grants no
  // access until an administrator restores it.
  if (membership.status === 'SUSPENDED') {
    throw new AppError(
      403,
      'MEMBERSHIP_SUSPENDED',
      'Your membership of this workspace is suspended',
    );
  }

  if (
    membership.organizationRole &&
    !isOrganizationRoleForWorkspace(workspace.type, membership.organizationRole)
  ) {
    throw new AppError(
      403,
      'ORGANIZATION_ROLE_WORKSPACE_MISMATCH',
      'The organization role is not valid for this workspace',
    );
  }

  const effectiveRole = effectiveWorkspaceRole(
    workspace.type,
    membership.role,
    membership.organizationRole,
  );

  if (!workspaceRoleCan(effectiveRole, input.capability)) {
    throw new AppError(
      403,
      'INSUFFICIENT_ROLE',
      'Your role in this workspace does not allow this action',
    );
  }

  // When a workspace requires SSO, only SSO sessions (or valid, time-limited break-glass
  // sessions for owners) may access it. Enforced when request auth/session context is provided.
  // This also invalidates access that existed before require-SSO was switched on.
  const hasRequestAuthContext = Boolean(input.auth?.sessionId || input.auth?.authMethod);
  if (hasRequestAuthContext) {
    const ssoConfig = await client.workspaceSsoConfig.findFirst({
      where: { workspaceId: workspace.id, isEnabled: true, requireSso: true },
      select: { breakGlassEnabled: true },
    });
    if (ssoConfig) {
      const verifiedDomainCount = await client.workspaceSsoDomain.count({
        where: { workspaceId: workspace.id, verifiedAt: { not: null } },
      });
      if (verifiedDomainCount > 0) {
        let authMethod = input.auth?.authMethod?.toLowerCase();
        let session: any = null;
        if (input.auth?.sessionId) {
          session = await client.session.findUnique({ where: { id: input.auth.sessionId } });
          if (session) authMethod = String(session.authMethod ?? 'PASSWORD').toLowerCase();
        }

        const isBreakGlassValid = () => {
          if (authMethod !== 'break_glass') return false;
          if (session?.authMethodExpiresAt && new Date(session.authMethodExpiresAt).getTime() <= Date.now()) return false;
          const isOwner = effectiveRole === 'OWNER' ||
            membership.organizationRole === 'COMPANY_OWNER' ||
            membership.organizationRole === 'INSTITUTION_OWNER';
          return Boolean(ssoConfig.breakGlassEnabled) && isOwner;
        };

        if (authMethod !== 'sso' && !isBreakGlassValid()) {
          throw new AppError(403, 'SSO_REQUIRED', 'This workspace requires SSO sign-in');
        }
      }
    }
  }

  return { workspace, membership, effectiveRole };
}

// ---------------------------------------------------------------------------
// Member management guards
// ---------------------------------------------------------------------------

/**
 * Asserts that the acting member may manage (change or remove) the target
 * member.
 *
 * Rules:
 * - The workspace owner is fixed and may not be changed or removed.
 * - A project manager may not change or remove another project manager; only
 *   the owner can do that, so a role can only be widened by the owner.
 */
export function assertMayManageMember(input: {
  actorRole: WorkspaceRole;
  targetRole: WorkspaceRole;
  targetIsOwner: boolean;
}): void {
  if (input.targetIsOwner) {
    throw new AppError(
      403,
      'OWNER_CANNOT_BE_MODIFIED',
      'The owner of a workspace cannot be changed or removed',
    );
  }

  if (input.actorRole !== 'OWNER' && input.targetRole === 'PROJECT_MANAGER') {
    throw new AppError(
      403,
      'INSUFFICIENT_ROLE',
      'Only the owner of a workspace can manage a project manager',
    );
  }
}

/**
 * Asserts that the acting workspace role may grant the requested role.
 * Project managers can manage lower-privilege members, but only the workspace
 * owner may grant project-manager privileges.
 */
export function assertMayAssignRole(input: {
  actorRole: WorkspaceRole;
  requestedRole: WorkspaceRole;
}): void {
  if (input.actorRole !== 'OWNER' && input.requestedRole === 'PROJECT_MANAGER') {
    throw new AppError(
      403,
      'INSUFFICIENT_ROLE',
      'Only the owner of a workspace can grant the project manager role',
    );
  }
}

/**
 * Asserts that removing the given member does not leave the workspace
 * without an owner.
 *
 * This guard only applies when the actor is removing themselves (self-
 * removal) and they are the current owner.  It ensures the workspace is
 * never left in a permanently ownerless state.
 */
export function assertOwnershipSafe(input: {
  actorId: string;
  targetUserId: string;
  targetRole: WorkspaceRole;
  workspaceOwnerId: string;
}): void {
  const isSelfRemoval = input.actorId === input.targetUserId;
  const targetIsOwner = input.targetUserId === input.workspaceOwnerId;

  if (isSelfRemoval && targetIsOwner) {
    throw new AppError(
      403,
      'OWNER_CANNOT_LEAVE',
      'The workspace owner cannot remove themselves. Transfer ownership first.',
    );
  }
}

import crypto from 'node:crypto';
import { createLocalJWKSet, createRemoteJWKSet, jwtVerify, type JSONWebKeySet } from 'jose';
import { getPrismaClient } from '../../db/prisma';
import { AppError } from '../../utils/errors';
import { encryptIntegrationToken, decryptIntegrationToken } from '../integrations/token-crypto';
import type { AppConfig } from '../../config/env';
import type { AuthService } from '../auth/auth.service';

export const SSO_BROWSER_BINDING_COOKIE = 'nexus_sso_oidc_binding';
const DEFAULT_CLOCK_SKEW_SEC = 60;

export interface VerifySsoIdTokenOptions {
  jwks: JSONWebKeySet;
  issuer: string;
  audience: string;
  nonce: string;
  clockSkewSec?: number;
}

export interface SsoIdpClaims {
  iss?: string;
  aud?: string | string[];
  sub?: string;
  email?: string;
  email_verified?: boolean;
  nonce?: string;
  exp?: number;
  iat?: number;
  name?: string;
  [key: string]: unknown;
}

export async function verifySsoIdToken(
  idToken: string,
  options: VerifySsoIdTokenOptions,
): Promise<SsoIdpClaims> {
  const jwks = createLocalJWKSet(options.jwks);
  const { payload } = await jwtVerify(idToken, jwks, {
    issuer: options.issuer,
    audience: options.audience,
    clockTolerance: options.clockSkewSec ?? DEFAULT_CLOCK_SKEW_SEC,
  });

  const claims = payload as SsoIdpClaims;
  if (!claims.nonce || claims.nonce !== options.nonce) {
    throw new AppError(401, 'SSO_INVALID_NONCE', 'SSO ID token nonce is invalid');
  }
  return claims;
}

export function assertVerifiedIdpEmail(claims: { email?: string; email_verified?: boolean }): string {
  const email = typeof claims.email === 'string' ? claims.email.trim().toLowerCase() : '';
  if (!email) {
    throw new AppError(401, 'SSO_EMAIL_MISSING', 'SSO identity provider did not return an email address');
  }
  if (claims.email_verified !== true) {
    throw new AppError(401, 'SSO_EMAIL_UNVERIFIED', 'SSO identity provider email is not verified');
  }
  return email;
}

export function isEmailDomainAllowed(email: string, verifiedDomains: string[]): boolean {
  const domain = email.split('@')[1]?.trim().toLowerCase();
  if (!domain) return false;
  const allowed = verifiedDomains.map((d) => d.trim().toLowerCase()).filter(Boolean);
  return allowed.includes(domain);
}

export function canLinkSsoIdentity(input: {
  idpEmailVerified: boolean;
  domainVerified: boolean;
  existingAccountEmailVerified: boolean;
}): boolean {
  return Boolean(input.idpEmailVerified && input.domainVerified && input.existingAccountEmailVerified);
}

export function encryptClientSecret(plain: string): string {
  return encryptIntegrationToken(plain);
}

export function decryptClientSecret(ciphertext: string): string {
  return decryptIntegrationToken(ciphertext);
}

function hashValue(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

export interface CreateSsoOidcStateInput {
  workspaceId: string;
  configId?: string | null;
  browserBindingValue: string;
  redirectUri?: string | null;
  ttlMs?: number;
}

export interface CreatedSsoOidcState {
  state: string;
  nonce: string;
  codeVerifier: string;
  expiresAt: Date;
}

export async function createSsoOidcState(
  input: CreateSsoOidcStateInput,
  db = getPrismaClient(),
): Promise<CreatedSsoOidcState> {
  const state = crypto.randomBytes(32).toString('base64url');
  const nonce = crypto.randomBytes(24).toString('base64url');
  const codeVerifier = crypto.randomBytes(32).toString('base64url');
  const ttlMs = input.ttlMs ?? 10 * 60 * 1000;
  const expiresAt = new Date(Date.now() + ttlMs);

  try {
    await db.ssoOidcState.create({
      data: {
        workspaceId: input.workspaceId,
        configId: input.configId ?? null,
        stateHash: hashValue(state),
        nonce,
        codeVerifier,
        browserBindingHash: hashValue(input.browserBindingValue),
        redirectUri: input.redirectUri ?? null,
        expiresAt,
      },
    });
  } catch {
    throw new AppError(503, 'SSO_STATE_STORE_UNAVAILABLE', 'SSO state store is unavailable');
  }

  return { state, nonce, codeVerifier, expiresAt };
}

export async function consumeSsoOidcState(
  input: { state: string; browserBindingValue: string; workspaceId?: string },
  db = getPrismaClient(),
): Promise<{ workspaceId: string; configId: string | null; nonce: string; codeVerifier: string; redirectUri: string | null }> {
  const stateHash = hashValue(input.state);
  const browserBindingHash = hashValue(input.browserBindingValue);

  try {
    const record = await db.ssoOidcState.findUnique({ where: { stateHash } });
    if (!record) {
      throw new AppError(400, 'SSO_STATE_INVALID', 'SSO state is invalid or expired');
    }
    if (record.consumedAt) {
      throw new AppError(400, 'SSO_STATE_REPLAYED', 'SSO state has already been used');
    }
    if (record.expiresAt.getTime() <= Date.now()) {
      throw new AppError(400, 'SSO_STATE_EXPIRED', 'SSO state has expired');
    }
    if (record.browserBindingHash !== browserBindingHash) {
      throw new AppError(400, 'SSO_STATE_INVALID', 'SSO state browser binding mismatch');
    }
    if (input.workspaceId && record.workspaceId !== input.workspaceId) {
      throw new AppError(400, 'SSO_STATE_INVALID', 'SSO state workspace mismatch');
    }

    const updated = await db.ssoOidcState.updateMany({
      where: { id: record.id, consumedAt: null },
      data: { consumedAt: new Date() },
    });
    if (updated.count !== 1) {
      throw new AppError(400, 'SSO_STATE_REPLAYED', 'SSO state has already been used');
    }

    return {
      workspaceId: record.workspaceId,
      configId: record.configId,
      nonce: record.nonce,
      codeVerifier: record.codeVerifier,
      redirectUri: record.redirectUri,
    };
  } catch (err) {
    if (err instanceof AppError) throw err;
    throw new AppError(503, 'SSO_STATE_STORE_UNAVAILABLE', 'SSO state store is unavailable');
  }
}

export function createPkceChallenge(codeVerifier: string): { codeChallenge: string; codeChallengeMethod: 'S256' } {
  const codeChallenge = crypto.createHash('sha256').update(codeVerifier).digest('base64url');
  return { codeChallenge, codeChallengeMethod: 'S256' };
}

export interface OidcDiscovery {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  jwks_uri: string;
}

export async function discoverOidcIssuer(issuer: string, fetchFn: typeof fetch = fetch): Promise<OidcDiscovery> {
  const url = `${issuer.replace(/\/+$/, '')}/.well-known/openid-configuration`;
  const res = await fetchFn(url, { headers: { accept: 'application/json' } });
  if (!res.ok) {
    throw new AppError(502, 'SSO_IDP_DISCOVERY_FAILED', 'Failed to discover OIDC issuer configuration');
  }
  const doc = (await res.json()) as Partial<OidcDiscovery>;
  if (!doc.authorization_endpoint || !doc.token_endpoint || !doc.jwks_uri || !doc.issuer) {
    throw new AppError(502, 'SSO_IDP_DISCOVERY_FAILED', 'OIDC issuer configuration is incomplete');
  }
  return doc as OidcDiscovery;
}

export async function fetchJwks(jwksUri: string, fetchFn: typeof fetch = fetch): Promise<JSONWebKeySet> {
  const res = await fetchFn(jwksUri, { headers: { accept: 'application/json' } });
  if (!res.ok) {
    throw new AppError(502, 'SSO_IDP_JWKS_FAILED', 'Failed to fetch OIDC provider JWKS');
  }
  return (await res.json()) as JSONWebKeySet;
}

export async function exchangeAuthorizationCode(input: {
  tokenEndpoint: string;
  clientId: string;
  clientSecret?: string | null;
  code: string;
  redirectUri: string;
  codeVerifier: string;
  fetchFn?: typeof fetch;
}): Promise<{ id_token: string; access_token?: string }> {
  const body = new URLSearchParams({
    grant_type: 'authorization_code',
    code: input.code,
    redirect_uri: input.redirectUri,
    client_id: input.clientId,
    code_verifier: input.codeVerifier,
  });
  const headers: Record<string, string> = { 'content-type': 'application/x-www-form-urlencoded' };
  if (input.clientSecret) {
    // basic auth preferred but some providers accept in body; basic auth is fine
    const basic = Buffer.from(`${input.clientId}:${input.clientSecret}`).toString('base64');
    headers.authorization = `Basic ${basic}`;
  }
  const res = await (input.fetchFn ?? fetch)(input.tokenEndpoint, { method: 'POST', headers, body });
  if (!res.ok) {
    throw new AppError(401, 'SSO_CODE_EXCHANGE_FAILED', 'Failed to exchange authorization code');
  }
  const json = (await res.json()) as { id_token?: string; access_token?: string };
  if (!json.id_token) {
    throw new AppError(401, 'SSO_ID_TOKEN_MISSING', 'Identity provider did not return an ID token');
  }
  return { id_token: json.id_token, access_token: json.access_token };
}

export async function verifyIdTokenWithRemoteJwks(input: {
  idToken: string;
  jwksUri: string;
  issuer: string;
  audience: string;
  nonce: string;
  clockSkewSec?: number;
  fetchFn?: typeof fetch;
}): Promise<SsoIdpClaims> {
  const jwks = await fetchJwks(input.jwksUri, input.fetchFn);
  return verifySsoIdToken(input.idToken, {
    jwks,
    issuer: input.issuer,
    audience: input.audience,
    nonce: input.nonce,
    clockSkewSec: input.clockSkewSec ?? DEFAULT_CLOCK_SKEW_SEC,
  });
}

export async function getVerifiedDomainsForWorkspace(workspaceId: string, db = getPrismaClient()): Promise<string[]> {
  const domains = await db.workspaceSsoDomain.findMany({
    where: { workspaceId, verifiedAt: { not: null } },
    select: { domain: true },
  });
  return domains.map((d) => d.domain.toLowerCase());
}

export async function resolveSsoUser(input: {
  workspaceId: string;
  email: string;
  emailVerifiedByIdp: boolean;
  jitEnabled: boolean;
  domainVerified: boolean;
  sub: string;
  provider: string;
  name?: string | null;
}, db = getPrismaClient()): Promise<{ userId: string; created: boolean }> {
  // Only link to existing account by VERIFIED email from IdP and verified workspace domain.
  if (!input.emailVerifiedByIdp) {
    throw new AppError(401, 'SSO_EMAIL_UNVERIFIED', 'SSO identity provider email is not verified');
  }
  if (!input.domainVerified) {
    throw new AppError(403, 'SSO_DOMAIN_NOT_VERIFIED', 'Email domain is not verified for this workspace');
  }

  const normalizedEmail = input.email.trim().toLowerCase();

  // Check external identity link first (same provider+subject in this workspace context is handled by provider scoping;
  // we use provider name + sub for uniqueness across providers)
  const providerKey = `${input.provider}:${input.workspaceId}`;
  const existingIdentity = await db.externalIdentity.findUnique({
    where: { provider_providerSubjectId: { provider: providerKey, providerSubjectId: input.sub } },
    select: { userId: true },
  });

  if (existingIdentity) {
    // Ensure linked account still has verified email and belongs/is allowed; do not allow takeover via changed email.
    const user = await db.user.findUnique({ where: { id: existingIdentity.userId }, select: { id: true, email: true, emailVerifiedAt: true, deletedAt: true } });
    if (!user || user.deletedAt) {
      throw new AppError(401, 'SSO_IDENTITY_INVALID', 'Linked account is not available');
    }
    // If account email changed to something different/unverified in risky way, require verified match for safety.
    if (user.email.toLowerCase() !== normalizedEmail) {
      // account takeover via email change protection: require both verified and matching/explicit re-link policy.
      // Do not auto-link/rebind; require manual resolution.
      throw new AppError(403, 'SSO_EMAIL_CHANGE_CONFLICT', 'SSO email does not match the linked account');
    }
    if (!user.emailVerifiedAt) {
      throw new AppError(403, 'SSO_ACCOUNT_EMAIL_UNVERIFIED', 'Linked account email is not verified');
    }
    return { userId: user.id, created: false };
  }

  // Try to find existing account by verified email only
  const existingUser = await db.user.findUnique({
    where: { email: normalizedEmail },
    select: { id: true, emailVerifiedAt: true, deletedAt: true },
  });

  if (existingUser) {
    if (existingUser.deletedAt) {
      throw new AppError(403, 'SSO_ACCOUNT_UNAVAILABLE', 'Account is not available');
    }
    if (!existingUser.emailVerifiedAt) {
      // Never auto-link an unverified email
      throw new AppError(403, 'SSO_ACCOUNT_EMAIL_UNVERIFIED', 'Existing account email is not verified');
    }
    // Link identity to verified existing account
    await db.externalIdentity.create({
      data: {
        userId: existingUser.id,
        provider: providerKey,
        providerSubjectId: input.sub,
      },
    });
    return { userId: existingUser.id, created: false };
  }

  // JIT creation only if workspace enables it
  if (!input.jitEnabled) {
    throw new AppError(403, 'SSO_JIT_DISABLED', 'Just-in-time provisioning is not enabled for this workspace');
  }

  // Create new user (SSO-provisioned). Password is random/unusable; user authenticates via SSO.
  const randomPasswordHash = crypto.createHash('sha256').update(crypto.randomBytes(32)).digest('hex');
  const created = await db.$transaction(async (tx) => {
    const user = await tx.user.create({
      data: {
        email: normalizedEmail,
        name: input.name?.trim() || normalizedEmail.split('@')[0] || 'SSO User',
        passwordHash: randomPasswordHash,
        status: 'ACTIVE',
        emailVerifiedAt: new Date(), // verified by IdP
      },
      select: { id: true },
    });
    await tx.externalIdentity.create({
      data: {
        userId: user.id,
        provider: providerKey,
        providerSubjectId: input.sub,
      },
    });
    // Ensure workspace membership if needed? JIT provisioning into workspace context -
    // at minimum we create identity; membership provisioning depends on product rules.
    // Create active membership for workspace if not personal-only context.
    await tx.workspaceMembership.upsert({
      where: { workspaceId_userId: { workspaceId: input.workspaceId, userId: user.id } },
      update: { status: 'ACTIVE' },
      create: {
        workspaceId: input.workspaceId,
        userId: user.id,
        role: 'MEMBER',
        status: 'ACTIVE',
      },
    }).catch(() => undefined);
    return user;
  });

  return { userId: created.id, created: true };
}

import crypto from 'node:crypto';
import zlib from 'node:zlib';
import { SAML, ValidateInResponseTo, type SamlConfig } from '@node-saml/node-saml';
import { getPrismaClient } from '../../db/prisma';
import { AppError } from '../../utils/errors';
import {
  assertVerifiedIdpEmail,
  isEmailDomainAllowed,
  getVerifiedDomainsForWorkspace,
  resolveSsoUser,
} from './oidc.service';

export const SSO_SAML_BINDING_COOKIE = 'nexus_sso_saml_binding';

function hashValue(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

export interface CreateSamlRequestStateInput {
  workspaceId: string;
  configId?: string | null;
  requestId: string;
  browserBindingValue: string;
  relayState?: string | null;
  ttlMs?: number;
}

export async function createSamlRequestState(
  input: CreateSamlRequestStateInput,
  db = getPrismaClient(),
): Promise<void> {
  const ttlMs = input.ttlMs ?? 10 * 60 * 1000;
  const expiresAt = new Date(Date.now() + ttlMs);
  try {
    await db.ssoSamlRequestState.create({
      data: {
        workspaceId: input.workspaceId,
        configId: input.configId ?? null,
        requestId: input.requestId,
        requestIdHash: hashValue(input.requestId),
        browserBindingHash: hashValue(input.browserBindingValue),
        relayState: input.relayState ?? null,
        expiresAt,
      },
    });
  } catch {
    throw new AppError(503, 'SSO_STATE_STORE_UNAVAILABLE', 'SSO state store is unavailable');
  }
}

export async function consumeSamlRequestState(
  input: { requestId: string; browserBindingValue: string; workspaceId?: string },
  db = getPrismaClient(),
): Promise<{ workspaceId: string; configId: string | null; relayState: string | null }> {
  const requestIdHash = hashValue(input.requestId);
  const browserBindingHash = hashValue(input.browserBindingValue);
  try {
    const record = await db.ssoSamlRequestState.findUnique({ where: { requestIdHash } });
    if (!record) {
      throw new AppError(400, 'SSO_SAML_INRESPONSETO_INVALID', 'SAML InResponseTo is invalid or expired');
    }
    if (record.consumedAt) {
      throw new AppError(400, 'SSO_SAML_REPLAYED', 'SAML response has already been used');
    }
    if (record.expiresAt.getTime() <= Date.now()) {
      throw new AppError(400, 'SSO_SAML_REQUEST_EXPIRED', 'SAML request has expired');
    }
    if (record.browserBindingHash !== browserBindingHash) {
      throw new AppError(400, 'SSO_SAML_STATE_INVALID', 'SAML browser binding mismatch');
    }
    if (input.workspaceId && record.workspaceId !== input.workspaceId) {
      throw new AppError(400, 'SSO_SAML_STATE_INVALID', 'SAML request workspace mismatch');
    }
    if (record.requestId !== input.requestId) {
      throw new AppError(400, 'SSO_SAML_INRESPONSETO_INVALID', 'SAML InResponseTo mismatch');
    }
    const updated = await db.ssoSamlRequestState.updateMany({
      where: { id: record.id, consumedAt: null },
      data: { consumedAt: new Date() },
    });
    if (updated.count !== 1) {
      throw new AppError(400, 'SSO_SAML_REPLAYED', 'SAML response has already been used');
    }
    return { workspaceId: record.workspaceId, configId: record.configId, relayState: record.relayState };
  } catch (err) {
    if (err instanceof AppError) throw err;
    throw new AppError(503, 'SSO_STATE_STORE_UNAVAILABLE', 'SSO state store is unavailable');
  }
}

export interface SamlValidationConfig {
  entryPoint?: string;
  issuer: string; // SP entity ID / audience
  callbackUrl: string; // ACS/destination
  idpIssuer: string; // expected IdP issuer
  idpCert: string; // pinned IdP signing certificate from admin metadata
  wantAssertionsSigned?: boolean;
  wantAuthnResponseSigned?: boolean;
  validateInResponseTo: ValidateInResponseTo;
  requestId?: string;
  audience?: string;
}

export function createSamlValidator(config: SamlValidationConfig): SAML {
  const samlConfig: SamlConfig = {
    entryPoint: config.entryPoint ?? 'https://idp.invalid/sso',
    issuer: config.issuer,
    callbackUrl: config.callbackUrl,
    idpIssuer: config.idpIssuer,
    idpCert: config.idpCert,
    audience: config.audience ?? config.issuer,
    wantAssertionsSigned: config.wantAssertionsSigned ?? true,
    wantAuthnResponseSigned: config.wantAuthnResponseSigned ?? false,
    validateInResponseTo: config.validateInResponseTo,
    ...(config.requestId ? { requestIdExpirationPeriodMs: 10 * 60 * 1000 } : {}),
    // @node-saml/node-saml validates conditions (NotBefore/NotOnOrAfter), audience, destination/recipient (callbackUrl),
    // issuer (idpIssuer), InResponseTo when configured, and signatures via xml-crypto (no hand-written validation).
    acceptedClockSkewMs: 60_000,
  } as SamlConfig;
  return new SAML(samlConfig);
}



export async function generateSamlAuthorizeRedirect(input: {
  config: SamlValidationConfig;
  relayState?: string | null;
}): Promise<{ redirectUrl: string; requestId: string }> {
  const saml = createSamlValidator(input.config);
  const requestXml = await (saml as any).generateAuthorizeRequestAsync(false);
  const m = String(requestXml).match(/\bID=(["'])([^"']+)\1/);
  if (!m?.[2]) {
    throw new AppError(500, 'SSO_SAML_REQUEST_INVALID', 'Failed to generate SAML AuthnRequest');
  }
  const requestId = m[2];
  const samlRequest = zlib.deflateRawSync(Buffer.from(String(requestXml))).toString('base64');
  const base = input.config.entryPoint;
  if (!base) throw new AppError(400, 'SSO_CONFIG_INVALID', 'SAML IdP SSO URL is not configured');
  const url = new URL(base);
  url.searchParams.set('SAMLRequest', samlRequest);
  if (input.relayState) url.searchParams.set('RelayState', input.relayState);
  // If SP signing is configured in future, SigAlg/Signature would be added; node-saml handles when options set.
  return { redirectUrl: url.toString(), requestId };
}

export function extractInResponseToFromSamlResponse(samlResponseBase64: string): string | undefined {
  try {
    const xml = Buffer.from(samlResponseBase64, 'base64').toString('utf8');
    // Match Response-level InResponseTo first (common); fallback to any InResponseTo.
    const resp = xml.match(/<(?:\w+:)?Response\b[^>]*\bInResponseTo=(["'])([^"']+)\1/);
    if (resp?.[2]) return resp[2];
    const any = xml.match(/\bInResponseTo=(["'])([^"']+)\1/);
    return any?.[2];
  } catch {
    return undefined;
  }
}

export async function validateSamlResponse(input: {
  samlResponseXmlOrBase64: string;
  config: SamlValidationConfig;
}): Promise<{ profile: Record<string, unknown>; loggedOut: boolean }> {
  const saml = createSamlValidator(input.config);
  const body = { SAMLResponse: input.samlResponseXmlOrBase64 };
  const result = await saml.validatePostResponseAsync(body);
  if (!result.profile) {
    throw new AppError(401, 'SSO_SAML_INVALID_ASSERTION', 'SAML assertion is invalid');
  }
  return { profile: result.profile as Record<string, unknown>, loggedOut: Boolean(result.loggedOut) };
}

export function extractSamlEmailAndName(profile: Record<string, unknown>): { email?: string; emailVerified?: boolean; name?: string; nameId?: string } {
  const nameId = typeof profile.nameID === 'string' ? profile.nameID : (typeof profile.nameID === 'object' && profile.nameID && 'value' in (profile.nameID as any) ? String((profile.nameID as any).value) : undefined);
  // Common attribute names
  const email =
    (typeof profile.email === 'string' && profile.email) ||
    (typeof profile['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress'] === 'string' && profile['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress']) ||
    (typeof profile.mail === 'string' && profile.mail) ||
    (nameId && nameId.includes('@') ? nameId : undefined);
  const name =
    (typeof profile.displayName === 'string' && profile.displayName) ||
    (typeof profile['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name'] === 'string' && profile['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name']) ||
    undefined;
  // SAML doesn't have a universal email_verified claim; for SAML we treat assertion from trusted/pinned IdP+verified domain as verified email source
  // when admin explicitly configures it. For strict "verified email from IdP" parity with OIDC, require explicit attribute/flag.
  const emailVerified =
    profile.email_verified === true ||
    profile.emailVerified === true ||
    profile['http://schemas.auth0.com/email_verified'] === true ||
    profile['http://schemas.auth0.com/email_verified'] === 'true';
  return { email: email ? String(email).toLowerCase() : undefined, emailVerified, name, nameId };
}

export async function resolveSamlUser(input: {
  workspaceId: string;
  configId: string;
  email: string;
  emailVerifiedByIdp: boolean;
  sub: string;
  name?: string | null;
}, db = getPrismaClient()) {
  const config = await db.workspaceSsoConfig.findFirst({ where: { id: input.configId, workspaceId: input.workspaceId, providerType: 'SAML' } });
  if (!config) throw new AppError(404, 'SSO_CONFIG_NOT_FOUND', 'SAML configuration not found');
  const verifiedDomains = await getVerifiedDomainsForWorkspace(input.workspaceId, db);
  const domainVerified = isEmailDomainAllowed(input.email, verifiedDomains);
  return resolveSsoUser({
    workspaceId: input.workspaceId,
    email: input.email,
    emailVerifiedByIdp: input.emailVerifiedByIdp,
    jitEnabled: config.jitProvisioningEnabled,
    domainVerified,
    sub: input.sub,
    provider: `saml:${config.providerName}`,
    name: input.name ?? null,
  }, db);
}

