    const token = await signIdToken(privateKey, {
      iss: 'https://issuer.example',
      aud: 'client-123',
      sub: 'user-sub',
      email: 'user@verified.example',
      email_verified: true,
      nonce: 'nonce-1',
      exp: now + 300,
      iat: now,
