  test('rejects wrong nonce', async () => {
    const { privateKey, jwks, kid } = await makeJwks();
    const now = Math.floor(Date.now() / 1000);
    const token = await signIdToken(privateKey, {
      iss: 'https://issuer.example',
      aud: 'client-123',
      sub: 'user-sub',
      email_verified: true,
      nonce: 'wrong-nonce',
      exp: now + 300,
      iat: now,
    }, { alg: 'RS256', kid });

    const { verifySsoIdToken } = await import('../src/modules/sso/oidc.service');
    await assert.rejects(
      () => verifySsoIdToken(token, {
        jwks,
        issuer: 'https://issuer.example',
        audience: 'client-123',
        nonce: 'expected-nonce',
        clockSkewSec: 60,
      }),
    );
  });
});

describe('SSO OIDC - DB-backed state/nonce (fail closed, single-use)', () => {
  test('replayed state is rejected (single-use)', async () => {
    const { consumeSsoOidcState } = await import('../src/modules/sso/oidc.service');
    const state = 'state-value';
    const browser = 'browser-cookie';
    const stateHash = crypto.createHash('sha256').update(state).digest('hex');
    const browserHash = crypto.createHash('sha256').update(browser).digest('hex');
    let consumed = false;
    const db = {
      ssoOidcState: {
        findUnique: async () => ({
          id: 'st1',
          workspaceId: 'ws1',
          configId: 'cfg1',
          stateHash,
          nonce: 'nonce-1',
          codeVerifier: 'verifier',
          browserBindingHash: browserHash,
          redirectUri: null,
          expiresAt: new Date(Date.now() + 60000),
          consumedAt: consumed ? new Date() : null,
        }),
        updateMany: async ({ where }: any) => {
          if (consumed || where.consumedAt !== null) return { count: 0 };
          consumed = true;
          return { count: 1 };
        },
      },
    } as any;

    const first = await consumeSsoOidcState({ state, browserBindingValue: browser }, db);
    assert.equal(first.workspaceId, 'ws1');
    await assert.rejects(
      () => consumeSsoOidcState({ state, browserBindingValue: browser }, db),
      (err: any) => err?.code === 'SSO_STATE_REPLAYED' || err?.message?.includes('already been used'),
    );
  });

  test('fails closed when state store is unavailable', async () => {
    const { createSsoOidcState, consumeSsoOidcState } = await import('../src/modules/sso/oidc.service');
    const brokenDb = {
      ssoOidcState: {
        create: async () => { throw new Error('db down'); },
        findUnique: async () => { throw new Error('db down'); },
        updateMany: async () => { throw new Error('db down'); },
      },
    } as any;

    await assert.rejects(
      () => createSsoOidcState({ workspaceId: 'ws1', browserBindingValue: 'b' }, brokenDb),
      (err: any) => err?.code === 'SSO_STATE_STORE_UNAVAILABLE',
    );
    await assert.rejects(
      () => consumeSsoOidcState({ state: 's', browserBindingValue: 'b' }, brokenDb),
      (err: any) => err?.code === 'SSO_STATE_STORE_UNAVAILABLE',
    );
  });

  test('rejects cross-workspace state use (workspace binding)', async () => {
    const { consumeSsoOidcState } = await import('../src/modules/sso/oidc.service');
    const state = 'state-value';
    const browser = 'browser-cookie';
    const stateHash = crypto.createHash('sha256').update(state).digest('hex');
    const browserHash = crypto.createHash('sha256').update(browser).digest('hex');
    const db = {
      ssoOidcState: {
        findUnique: async () => ({
          id: 'st1',
          workspaceId: 'ws1',
          configId: 'cfg1',
          stateHash,
          nonce: 'nonce-1',
          codeVerifier: 'verifier',
          browserBindingHash: browserHash,
          redirectUri: null,
          expiresAt: new Date(Date.now() + 60000),
          consumedAt: null,
        }),
        updateMany: async () => ({ count: 1 }),
      },
    } as any;

    await assert.rejects(
      () => consumeSsoOidcState({ state, browserBindingValue: browser, workspaceId: 'ws2' }, db),
      (err: any) => err?.code === 'SSO_STATE_INVALID',
    );
  });
});

describe('SSO OIDC - policy checks (pure)', () => {
  test('rejects unverified email from IdP (email_verified false)', async () => {
    const { assertVerifiedIdpEmail } = await import('../src/modules/sso/oidc.service');
    assert.throws(() => assertVerifiedIdpEmail({ email: 'user@example.com', email_verified: false }));
  });

  test('rejects missing email_verified claim', async () => {
    const { assertVerifiedIdpEmail } = await import('../src/modules/sso/oidc.service');
    assert.throws(() => assertVerifiedIdpEmail({ email: 'user@example.com' } as any));
  });

  test('rejects domain not verified for workspace', async () => {
    const { isEmailDomainAllowed } = await import('../src/modules/sso/oidc.service');
    assert.equal(isEmailDomainAllowed('user@unverified.com', ['verified.com']), false);
  });

  test('cross-workspace isolation: domain verified in other workspace does not grant access', async () => {
    const { isEmailDomainAllowed } = await import('../src/modules/sso/oidc.service');
    // Simulates workspace A verified domains only
    assert.equal(isEmailDomainAllowed('user@workspace-b.com', ['workspace-a.com']), false);
  });

  test('account takeover via email change: must not link by unverified changed email', async () => {
    const { canLinkSsoIdentity } = await import('../src/modules/sso/oidc.service');
    assert.equal(canLinkSsoIdentity({ idpEmailVerified: false, domainVerified: true, existingAccountEmailVerified: true }), false);
  });
});

describe('SSO enforcement - require SSO blocks password login paths', () => {
  test('userHasRequiredSsoWorkspace returns required when active membership is in SSO-required workspace', async () => {
    const { userHasRequiredSsoWorkspace } = await import('../src/modules/sso/sso.service');
    const db = {
      workspaceMembership: {
        findMany: async () => [{ workspaceId: 'ws1' }],
      },
      workspaceSsoConfig: {
        findFirst: async () => ({ id: 'cfg1', isEnabled: true, requireSso: true, breakGlassEnabled: true }),
      },
      workspaceSsoDomain: {
        count: async () => 1,
      },
    } as never;
    const result = await userHasRequiredSsoWorkspace(db, 'user1');
    assert.equal(result.required, true);
    assert.equal(result.workspaceId, 'ws1');
  });

  test('assertUserPasswordLoginAllowed throws SSO_REQUIRED when workspace requires SSO', async () => {
    const { assertUserPasswordLoginAllowed } = await import('../src/modules/sso/sso.service');
    const db = {
      workspaceMembership: {
        findMany: async () => [{ workspaceId: 'ws1' }],
      },
      workspaceSsoConfig: {
        findFirst: async () => ({ id: 'cfg1', isEnabled: true, requireSso: true, breakGlassEnabled: false }),
      },
      workspaceSsoDomain: {
        count: async () => 1,
      },
    } as never;
    await assert.rejects(
      () => assertUserPasswordLoginAllowed(db, 'user1'),
      (err: unknown) => (err as { code?: string })?.code === 'SSO_REQUIRED',
    );
  });

  test('assertUserPasswordLoginAllowed allows when no workspace requires SSO', async () => {
    const { assertUserPasswordLoginAllowed } = await import('../src/modules/sso/sso.service');
    const db = {
      workspaceMembership: {
        findMany: async () => [{ workspaceId: 'ws1' }],
      },
      workspaceSsoConfig: {
        findFirst: async () => null,
      },
    } as never;
    await assert.doesNotReject(() => assertUserPasswordLoginAllowed(db, 'user1'));
  });
});

describe('SSO enforcement - config removal revokes sessions', () => {
  test('disableSsoConfig revokes active sessions when require-SSO was enabled', async () => {
    const { disableSsoConfig } = await import('../src/modules/sso/sso.service');
    let revokedCalls = 0;
    const db = {
      workspace: { findFirst: async () => ({ id: 'ws1', status: 'ACTIVE', type: 'COMPANY', deletedAt: null }) },
      workspaceMembership: {
        findUnique: async () => ({ id: 'm1', workspaceId: 'ws1', userId: 'admin1', role: 'OWNER', organizationRole: null, status: 'ACTIVE' }),
        findFirst: async () => ({ role: 'OWNER', organizationRole: null, status: 'ACTIVE' }),
        findMany: async () => [{ userId: 'u1' }, { userId: 'u2' }],
      },
      workspaceSsoConfig: {
        findFirst: async () => ({ id: 'cfg1', workspaceId: 'ws1', isEnabled: true, requireSso: true }),
        update: async () => ({ id: 'cfg1', isEnabled: false, requireSso: false, status: 'DISABLED' }),
      },
      session: {
        updateMany: async () => { revokedCalls++; return { count: 1 }; },
      },
      auditLog: { create: async () => ({}) },
    } as never;
    const result = await disableSsoConfig(db, 'admin1', 'ws1', 'cfg1');
    assert.equal(result.disabled, true);
    assert.equal(result.revokedSessions, 2);
    assert.equal(revokedCalls, 2);
  });
});

import assert from 'node:assert/strict';
import test, { describe } from 'node:test';
import crypto from 'node:crypto';
import { SignedXml } from 'xml-crypto';
import { validateSamlResponse } from '../src/modules/sso/saml.service';

import { execSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

function makeTestCert(): { key: string; cert: string } {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'saml-test-'));
  const keyPath = path.join(dir, 'key.pem');
  const certPath = path.join(dir, 'cert.pem');
  execSync(`openssl req -x509 -newkey rsa:2048 -keyout ${keyPath} -out ${certPath} -sha256 -days 1 -nodes -subj "/CN=TestIdP" 2>/dev/null`);
  const key = fs.readFileSync(keyPath, 'utf8');
  const cert = fs.readFileSync(certPath, 'utf8');
  return { key, cert };
}

const { key: IDP_KEY, cert: IDP_CERT } = makeTestCert();

function nowIso(offsetSec = 0) {
  return new Date(Date.now() + offsetSec * 1000).toISOString();
}

function buildSignedResponse(opts: {
  requestId?: string;
  audience?: string;
  issuer?: string;
  destination?: string;
  recipient?: string;
  notBefore?: string;
  notOnOrAfter?: string;
  nameId?: string;
  email?: string;
  emailVerified?: string;
  sign?: boolean;
  tamper?: boolean;
  wrapSignature?: boolean;
  inResponseTo?: string | null;
}) {
  const id = '_' + crypto.randomBytes(8).toString('hex');
  const assertionId = '_' + crypto.randomBytes(8).toString('hex');
  const issueInstant = nowIso();
  const notBefore = opts.notBefore ?? nowIso(-60);
  const notOnOrAfter = opts.notOnOrAfter ?? nowIso(300);
  const destination = opts.destination ?? 'https://sp.example.com/saml/acs';
  const recipient = opts.recipient ?? destination;
  const audience = opts.audience ?? 'https://sp.example.com';
  const issuer = opts.issuer ?? 'https://idp.example.com';
  const inResponseToAttr = opts.inResponseTo === null ? '' : ` InResponseTo="${opts.inResponseTo ?? opts.requestId ?? '_req1'}"`;
  const nameId = opts.nameId ?? 'user@example.com';
  const email = opts.email ?? 'user@example.com';

  const assertion = `
    <saml:Assertion xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="${assertionId}" IssueInstant="${issueInstant}" Version="2.0">
      <saml:Issuer>${issuer}</saml:Issuer>
      <saml:Subject>
        <saml:NameID Format="urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress">${nameId}</saml:NameID>
        <saml:SubjectConfirmation Method="urn:oasis:names:tc:SAML:2.0:cm:bearer">
          <saml:SubjectConfirmationData${inResponseToAttr} NotOnOrAfter="${notOnOrAfter}" Recipient="${recipient}"/>
        </saml:SubjectConfirmation>
      </saml:Subject>
      <saml:Conditions NotBefore="${notBefore}" NotOnOrAfter="${notOnOrAfter}">
        <saml:AudienceRestriction>
          <saml:Audience>${audience}</saml:Audience>
        </saml:AudienceRestriction>
      </saml:Conditions>
      <saml:AttributeStatement>
        <saml:Attribute Name="email"><saml:AttributeValue>${email}</saml:AttributeValue></saml:Attribute>
        ${opts.emailVerified !== undefined ? `<saml:Attribute Name="email_verified"><saml:AttributeValue>${opts.emailVerified}</saml:AttributeValue></saml:Attribute>` : ''}
      </saml:AttributeStatement>
    </saml:Assertion>`;

  let response = `<?xml version="1.0"?>
<samlp:Response xmlns:samlp="urn:oasis:names:tc:SAML:2.0:protocol" xmlns:saml="urn:oasis:names:tc:SAML:2.0:assertion" ID="${id}" Version="2.0" IssueInstant="${issueInstant}" Destination="${destination}"${inResponseToAttr}>
  <saml:Issuer>${issuer}</saml:Issuer>
  <samlp:Status><samlp:StatusCode Value="urn:oasis:names:tc:SAML:2.0:status:Success"/></samlp:Status>
  ${assertion}
</samlp:Response>`;

  if (opts.sign !== false) {
    const sig = new SignedXml({ privateKey: IDP_KEY, publicCert: IDP_CERT });
    sig.addReference({
      xpath: `//*[local-name(.)='Assertion' and @ID='${assertionId}']`,
      digestAlgorithm: 'http://www.w3.org/2001/04/xmlenc#sha256',
      transforms: ['http://www.w3.org/2001/10/xml-exc-c14n#', 'http://www.w3.org/2000/09/xmldsig#enveloped-signature'],
    });
    sig.canonicalizationAlgorithm = 'http://www.w3.org/2001/10/xml-exc-c14n#';
    sig.signatureAlgorithm = 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256';
    sig.computeSignature(response, { location: { reference: `//*[local-name(.)='Assertion' and @ID='${assertionId}']`, action: 'prepend' } });
    response = sig.getSignedXml();
  }

  if (opts.tamper) {
    response = response.replace(email, 'attacker@evil.com');
  }

  if (opts.wrapSignature) {
    // Signature wrapping attempt: insert a second unsigned assertion with different identity before signed one
    const evilAssertionId = '_' + crypto.randomBytes(8).toString('hex');
    const evilAssertion = assertion.replace(assertionId, evilAssertionId).replace(nameId, 'attacker@evil.com').replace(email, 'attacker@evil.com');
    response = response.replace(/<saml:Assertion/, evilAssertion + '\n<saml:Assertion');
  }

  return Buffer.from(response).toString('base64');
}

const baseConfig = {
  issuer: 'https://sp.example.com',
  callbackUrl: 'https://sp.example.com/saml/acs',
  idpIssuer: 'https://idp.example.com',
  idpCert: IDP_CERT,
  wantAssertionsSigned: true,
  validateInResponseTo: 'never' as const, // library cache not used in test; InResponseTo enforced separately in app state layer
  requestId: '_req1',
  audience: 'https://sp.example.com',
};

describe('SAML SSO validation (@node-saml/node-saml)', () => {
  test('rejects unsigned assertion', async () => {
    const saml = buildSignedResponse({ requestId: '_req1', sign: false });
    await assert.rejects(() => validateSamlResponse({ samlResponseXmlOrBase64: saml, config: baseConfig as never }));
  });

  test('rejects tampered signed assertion', async () => {
    const saml = buildSignedResponse({ requestId: '_req1', tamper: true });
    await assert.rejects(() => validateSamlResponse({ samlResponseXmlOrBase64: saml, config: baseConfig as never }));
  });

  test('rejects wrong audience', async () => {
    const saml = buildSignedResponse({ requestId: '_req1', audience: 'https://wrong-sp.example.com' });
    await assert.rejects(() => validateSamlResponse({ samlResponseXmlOrBase64: saml, config: baseConfig as never }));
  });

  test('rejects invalid InResponseTo (replay/unknown request) via state consumption', async () => {
    const { consumeSamlRequestState } = await import('../src/modules/sso/saml.service');
    // missing/unknown request id in state store => rejected (fail closed / replay protection)
    const db = { ssoSamlRequestState: { findUnique: async () => null } } as any;
    await assert.rejects(
      () => consumeSamlRequestState({ requestId: '_other', browserBindingValue: 'b' }, db),
      (err: unknown) => (err as { code?: string } | null)?.code === 'SSO_SAML_INRESPONSETO_INVALID',
    );
  });

  test('rejects signature-wrapping sample', async () => {
    const saml = buildSignedResponse({ requestId: '_req1', wrapSignature: true });
    await assert.rejects(() => validateSamlResponse({ samlResponseXmlOrBase64: saml, config: baseConfig as never }));
  });
});
